window.TEXTOS_SEED["ezequiel"][1] = [
{s:"Introdução"},
{v:1,t:"No trigésimo ano, no quarto mês, no dia cinco do mês, quando eu estava entre os deportados, junto ao rio Cobar, os céus se abriram, e tive visões de Deus.",n:"O trigésimo ano: talvez a idade do profeta. Cobar: canal do Eufrates, perto de Nipur, na Babilônia."},
{v:2,t:"No dia cinco do mês — era o quinto ano da deportação do rei Joaquin —,",n:"Em julho de 593 antes de Cristo."},
{v:3,t:"a palavra do Senhor foi dirigida a Ezequiel, filho de Buzi, sacerdote, na terra dos caldeus, junto ao rio Cobar; e ali a mão do Senhor esteve sobre ele."},
{s:"A visão da glória do Senhor"},
{v:4,t:"Olhei, e eis que um vento tempestuoso vinha do norte, uma grande nuvem e um fogo que se revolvia, com um esplendor ao redor; e no meio dele havia como que o brilho do electro, no meio do fogo.",n:"Electro: liga brilhante de ouro e prata; o sentido exato da palavra hebraica (hashmal) é incerto."},
{v:5,t:"E no meio havia a forma de quatro seres vivos, e esta era a sua aparência: tinham forma humana."},
{v:6,t:"Cada um tinha quatro faces, e cada um tinha quatro asas."},
{v:7,t:"As suas pernas eram retas, e a planta dos seus pés era como a planta do pé de um bezerro; e brilhavam como o bronze polido."},
{v:8,t:"Debaixo das asas, nos quatro lados, tinham mãos humanas. Os quatro tinham faces e asas;"},
{v:9,t:"as suas asas tocavam uma na outra; ao andar, não se voltavam: cada um andava para a frente."},
{v:10,t:"Quanto à forma das suas faces: os quatro tinham face de homem e face de leão à direita, face de touro à esquerda, e os quatro tinham face de águia.",np:1,n:"A tradição cristã viu nestas quatro faces os símbolos dos quatro evangelistas (compare Apocalipse 4,7)."},
{v:11,t:"Tinham as asas estendidas para o alto; cada um tinha duas asas que se tocavam e duas que lhe cobriam o corpo.",np:1},
{v:12,t:"Cada um andava para a frente: iam para onde o espírito os impelia, e não se voltavam ao andar."},
{v:13,t:"No meio dos seres vivos havia algo semelhante a brasas de fogo acesas, semelhante a tochas que se moviam entre os seres vivos; o fogo resplandecia, e do fogo saíam relâmpagos.",np:1},
{v:14,t:"E os seres vivos iam e vinham como o clarão do relâmpago."},
{v:15,t:"Enquanto eu olhava os seres vivos, vi uma roda no chão, ao lado de cada um dos quatro seres vivos.",np:1},
{v:16,t:"O aspecto das rodas e a sua estrutura eram como o brilho do crisólito, e as quatro tinham a mesma forma; o seu aspecto e a sua estrutura eram como se uma roda estivesse dentro da outra."},
{v:17,t:"Quando se moviam, iam nas quatro direções, sem se voltarem ao andar."},
{v:18,t:"Os seus aros eram altos e terríveis de ver; e os aros das quatro rodas estavam cheios de olhos ao redor."},
{v:19,t:"Quando os seres vivos andavam, as rodas andavam ao lado deles; e quando os seres vivos se elevavam da terra, as rodas também se elevavam."},
{v:20,t:"Iam para onde o espírito os impelia, e as rodas se elevavam junto com eles, pois o espírito dos seres vivos estava nas rodas."},
{v:21,t:"Quando eles andavam, elas andavam; quando eles paravam, elas paravam; e quando se elevavam da terra, as rodas se elevavam junto com eles, pois o espírito dos seres vivos estava nas rodas."},
{v:22,t:"Acima das cabeças dos seres vivos havia algo semelhante a um firmamento, com o brilho terrível do cristal, estendido sobre as suas cabeças.",np:1},
{v:23,t:"Debaixo do firmamento, as suas asas estavam estendidas, uma em direção à outra; cada um tinha duas asas que lhe cobriam o corpo."},
{v:24,t:"Ouvi o ruído das suas asas, como o ruído de muitas águas, como a voz do Todo-poderoso; quando andavam, era um estrondo como o de um exército; quando paravam, baixavam as asas.",np:1},
{v:25,t:"E quando se ouvia uma voz acima do firmamento que estava sobre as suas cabeças, eles paravam e baixavam as asas."},
{v:26,t:"Acima do firmamento que estava sobre as suas cabeças, havia algo semelhante a um trono, com o aspecto de pedra de safira; e sobre essa forma de trono, no alto, havia uma figura com aparência humana.",np:1},
{v:27,t:"Vi também algo como o brilho do electro, com aspecto de fogo ao redor, desde o que parecia ser a sua cintura para cima; e desde o que parecia ser a sua cintura para baixo, vi algo como fogo, e um esplendor ao seu redor."},
{v:28,t:"Como o aspecto do arco que aparece nas nuvens em dia de chuva, assim era o aspecto do esplendor ao redor. Era esta a aparência da imagem da glória do Senhor. Ao vê-la, caí com o rosto por terra e ouvi a voz de alguém que falava.",n:"Ezequiel acumula as comparações (algo semelhante, como que) para indicar que a glória de Deus supera toda descrição."}
];

window.TEXTOS_SEED["ezequiel"][2] = [
{s:"A missão do profeta"},
{v:1,t:"Ele me disse: Filho do homem, põe-te de pé, e eu falarei contigo.",n:"Filho do homem: em hebraico, ben-adam, isto é, ser humano, mortal; é assim que Deus chama o profeta ao longo do livro."},
{v:2,t:"Enquanto ele me falava, o espírito entrou em mim e me pôs de pé, e ouvi aquele que me falava.",np:1},
{v:3,t:"Ele me disse: Filho do homem, eu te envio aos filhos de Israel, a nações rebeldes, que se revoltaram contra mim; eles e os seus pais pecaram contra mim até hoje."},
{v:4,t:"São filhos de rosto duro e de coração obstinado aqueles a quem eu te envio; e tu lhes dirás: Assim diz o Senhor Deus."},
{v:5,t:"Quer escutem, quer não escutem — pois são uma casa rebelde —, saberão que houve um profeta no meio deles."},
{v:6,t:"E tu, filho do homem, não tenhas medo deles nem das suas palavras, ainda que estejas entre urtigas e espinhos e mores entre escorpiões; não tenhas medo das suas palavras nem te assustes diante deles, pois são uma casa rebelde."},
{v:7,t:"Tu lhes dirás as minhas palavras, quer escutem, quer não escutem, pois são rebeldes."},
{v:8,t:"E tu, filho do homem, escuta o que te digo: não sejas rebelde como essa casa rebelde; abre a boca e come o que te dou.",np:1},
{v:9,t:"Olhei, e eis que uma mão estava estendida para mim, e nela havia o rolo de um livro."},
{v:10,t:"Ele o desenrolou diante de mim: estava escrito por dentro e por fora, e nele estavam escritos lamentações, gemidos e ais."}
];

window.TEXTOS_SEED["ezequiel"][3] = [
{s:"O profeta come o rolo"},
{v:1,t:"Ele me disse: Filho do homem, come o que encontras diante de ti; come este rolo e vai falar à casa de Israel."},
{v:2,t:"Abri a boca, e ele me fez comer aquele rolo,"},
{v:3,t:"e me disse: Filho do homem, alimenta o teu ventre e enche as tuas entranhas com este rolo que te dou. Eu o comi, e na minha boca ele era doce como o mel.",n:"Compare Jeremias 15,16; Apocalipse 10,9–10."},
{v:4,t:"Ele me disse: Filho do homem, vai à casa de Israel e fala-lhes as minhas palavras."},
{v:5,t:"Pois não és enviado a um povo de fala obscura e de língua difícil, mas à casa de Israel;"},
{v:6,t:"não a povos numerosos de fala obscura e de língua difícil, cujas palavras não entenderias; se eu te enviasse a eles, eles te escutariam."},
{v:7,t:"Mas a casa de Israel não quererá escutar-te, porque não quer escutar-me; pois toda a casa de Israel tem a fronte dura e o coração obstinado."},
{v:8,t:"Eis que tornei o teu rosto tão duro como o rosto deles, e a tua fronte tão dura como a fronte deles;"},
{v:9,t:"fiz a tua fronte como o diamante, mais dura que a pederneira. Não tenhas medo deles nem te assustes diante deles, pois são uma casa rebelde.",n:"Jogo de palavras com o nome do profeta: Ezequiel significa Deus fortalece."},
{v:10,t:"Disse-me ainda: Filho do homem, todas as palavras que eu te disser, recebe-as no teu coração e ouve-as com os teus ouvidos."},
{v:11,t:"Vai aos deportados, aos filhos do teu povo; fala-lhes e dize-lhes: Assim diz o Senhor Deus; quer escutem, quer não escutem."},
{v:12,t:"Então o espírito me levantou, e ouvi atrás de mim o ruído de um grande estrondo, quando a glória do Senhor se elevou do seu lugar:",np:1,n:"Assim a Nova Vulgata, com uma pequena correção do hebraico, que diz: Bendita seja a glória do Senhor no seu lugar!"},
{v:13,t:"era o ruído das asas dos seres vivos, que batiam uma na outra, o ruído das rodas ao lado deles e o ruído de um grande estrondo."},
{v:14,t:"O espírito me levantou e me levou; e eu fui, amargurado e com o espírito irritado, enquanto a mão do Senhor pesava fortemente sobre mim."},
{v:15,t:"Cheguei aos deportados de Tel-Abib, que moravam junto ao rio Cobar, e fiquei sentado ali, onde eles moravam, durante sete dias, atordoado no meio deles.",np:1,n:"Tel-Abib: colina das espigas, aldeia de deportados na Babilônia."},
{s:"A sentinela de Israel"},
{v:16,t:"Ao fim dos sete dias, a palavra do Senhor me foi dirigida:"},
{v:17,t:"Filho do homem, eu te constituí sentinela para a casa de Israel; quando ouvires uma palavra da minha boca, tu os advertirás da minha parte."},
{v:18,t:"Se eu disser ao ímpio: Certamente morrerás, e tu não o advertires nem lhe falares para desviá-lo do seu mau caminho, a fim de que viva, esse ímpio morrerá pela sua iniquidade, mas eu pedirei contas do seu sangue a ti."},
{v:19,t:"Mas, se advertires o ímpio, e ele não se converter da sua impiedade e do seu mau caminho, ele morrerá pela sua iniquidade, mas tu terás salvado a tua vida."},
{v:20,t:"Se o justo se afastar da sua justiça e praticar o mal, eu porei diante dele uma pedra de tropeço, e ele morrerá; porque não o advertiste, morrerá no seu pecado, e as obras justas que praticou não serão lembradas; mas eu pedirei contas do seu sangue a ti."},
{v:21,t:"Se, porém, advertires o justo para que não peque, e ele não pecar, certamente viverá, porque foi advertido, e tu terás salvado a tua vida."},
{s:"O profeta mudo"},
{v:22,t:"Ali a mão do Senhor esteve sobre mim, e ele me disse: Levanta-te, sai para a planície, e lá falarei contigo."},
{v:23,t:"Levantei-me e saí para a planície, e eis que ali estava a glória do Senhor, como a glória que eu tinha visto junto ao rio Cobar; e caí com o rosto por terra."},
{v:24,t:"Então o espírito entrou em mim e me pôs de pé; ele falou comigo e me disse: Vai fechar-te em tua casa."},
{v:25,t:"E tu, filho do homem, eis que porão cordas sobre ti e te amarrarão com elas, e não poderás sair para o meio deles."},
{v:26,t:"Farei que a tua língua se cole ao teu palato, e ficarás mudo e não serás para eles alguém que os repreende, pois são uma casa rebelde."},
{v:27,t:"Mas, quando eu te falar, abrirei a tua boca, e tu lhes dirás: Assim diz o Senhor Deus. Quem quiser escutar, que escute; quem não quiser, que não escute, pois são uma casa rebelde."}
];

window.TEXTOS_SEED["ezequiel"][4] = [
{s:"O cerco de Jerusalém encenado"},
{v:1,t:"E tu, filho do homem, toma um tijolo, põe-no diante de ti e desenha nele uma cidade, Jerusalém.",n:"O profeta encena o cerco de Jerusalém (588–587 antes de Cristo) alguns anos antes de acontecer."},
{v:2,t:"Monta contra ela um cerco: constrói trincheiras, levanta uma rampa, põe acampamentos contra ela e coloca aríetes ao redor."},
{v:3,t:"Toma também uma assadeira de ferro e põe-na como um muro de ferro entre ti e a cidade; fixa o teu olhar nela, e ela ficará sitiada, e tu a cercarás: é um sinal para a casa de Israel."},
{v:4,t:"Depois deita-te sobre o lado esquerdo e põe sobre ele a iniquidade da casa de Israel; carregarás a iniquidade deles pelo número de dias em que ficares deitado sobre esse lado.",np:1},
{v:5,t:"Eu te fixo os anos da iniquidade deles num número de dias: trezentos e noventa dias; e carregarás a iniquidade da casa de Israel.",n:"Trezentos e noventa: assim o hebraico; a tradução grega diz cento e noventa. O sentido dos números é discutido."},
{v:6,t:"Quando os tiveres completado, tu te deitarás de novo, agora sobre o lado direito, e carregarás a iniquidade da casa de Judá durante quarenta dias; um dia por ano, eu te fixo um dia por ano."},
{v:7,t:"Voltarás o rosto para o cerco de Jerusalém, com o braço descoberto, e profetizarás contra ela."},
{v:8,t:"Eis que te amarrei com cordas, e não te virarás de um lado para o outro, até completares os dias do teu cerco."},
{s:"O pão do cerco"},
{v:9,t:"Toma também trigo, cevada, favas, lentilhas, milhete e espelta, põe tudo numa só vasilha e faze com isso o teu pão; tu o comerás durante os trezentos e noventa dias em que ficares deitado sobre o teu lado."},
{v:10,t:"A comida que comerás será pesada: vinte siclos por dia; tu a comerás de tempos em tempos.",n:"Cerca de duzentos e trinta gramas."},
{v:11,t:"Beberás também a água medida: a sexta parte de um hin; tu a beberás de tempos em tempos.",n:"Pouco mais de meio litro."},
{v:12,t:"Tu o comerás como pão de cevada cozido sob as cinzas; e o cozerás à vista deles sobre excrementos humanos."},
{v:13,t:"E o Senhor disse: Assim os filhos de Israel comerão o seu pão impuro entre as nações para onde eu os expulsarei."},
{v:14,t:"Eu disse: Ah, Senhor Deus! Eis que eu nunca me contaminei; desde a minha juventude até agora nunca comi animal morto ou despedaçado por feras, e nunca entrou na minha boca carne impura."},
{v:15,t:"Ele me respondeu: Pois bem, eu te permito usar esterco de boi em vez de excrementos humanos; sobre ele cozerás o teu pão."},
{v:16,t:"E me disse: Filho do homem, eis que vou quebrar o sustento do pão em Jerusalém; eles comerão o pão pesado e com ansiedade, e beberão a água medida e com angústia,"},
{v:17,t:"para que, faltando o pão e a água, fiquem consternados uns com os outros e definhem na sua iniquidade."}
];

window.TEXTOS_SEED["ezequiel"][5] = [
{s:"Os cabelos cortados: o destino de Jerusalém"},
{v:1,t:"E tu, filho do homem, toma uma espada afiada, usa-a como navalha de barbeiro e passa-a sobre a cabeça e a barba; depois toma uma balança e divide os pelos."},
{v:2,t:"Queimarás um terço no fogo, no meio da cidade, quando se completarem os dias do cerco; tomarás outro terço e o cortarás com a espada ao redor da cidade; e o último terço espalharás ao vento, e eu desembainharei a espada atrás deles."},
{v:3,t:"Tomarás deles um pequeno número e os amarrarás na barra do teu manto;"},
{v:4,t:"e destes ainda tomarás alguns, os jogarás no fogo e os queimarás; dali sairá um fogo. E dirás a toda a casa de Israel:"},
{v:5,t:"Assim diz o Senhor Deus: Esta é Jerusalém! Eu a pus no meio das nações, com os países ao seu redor."},
{v:6,t:"Mas ela se rebelou contra os meus decretos, com mais impiedade que as nações, e contra os meus preceitos, mais que os países que a rodeiam; pois rejeitaram os meus decretos e não andaram nos meus preceitos."},
{v:7,t:"Por isso assim diz o Senhor Deus: Porque fostes mais turbulentos que as nações que vos rodeiam, não andastes nos meus preceitos e não cumpristes os meus decretos, e nem sequer agistes segundo os costumes das nações que vos rodeiam,",np:1},
{v:8,t:"por isso assim diz o Senhor Deus: Eis que também eu estou contra ti, e executarei no meio de ti os meus julgamentos, à vista das nações."},
{v:9,t:"Farei em ti o que nunca fiz e o que nunca mais farei, por causa de todas as tuas abominações."},
{v:10,t:"Por isso, no meio de ti, os pais comerão os filhos, e os filhos comerão os pais; executarei em ti os meus julgamentos e espalharei a todos os ventos tudo o que restar de ti.",n:"Nota do tradutor: compare Levítico 26,29; Deuteronômio 28,53; Lamentações 4,10; o texto não foi suavizado."},
{v:11,t:"Por isso, pela minha vida, oráculo do Senhor Deus, porque profanaste o meu santuário com todas as tuas coisas detestáveis e com todas as tuas abominações, também eu te rasparei, sem que o meu olho tenha piedade, e não terei compaixão."},
{v:12,t:"Um terço de ti morrerá de peste e será consumido pela fome no meio de ti; um terço cairá pela espada ao teu redor; e o outro terço espalharei a todos os ventos, e desembainharei a espada atrás deles."},
{v:13,t:"Assim esgotarei a minha ira, saciarei neles o meu furor e ficarei satisfeito; e saberão que eu, o Senhor, falei no meu zelo, quando tiver esgotado neles o meu furor."},
{v:14,t:"Farei de ti uma ruína e um objeto de insulto entre as nações que te rodeiam, à vista de todos os que passarem."},
{v:15,t:"Serás objeto de insulto e de escárnio, uma lição e um espanto para as nações que te rodeiam, quando eu executar em ti os meus julgamentos com ira, furor e castigos violentos."},
{v:16,t:"Eu, o Senhor, falei. Quando eu lançar contra vós as flechas terríveis da fome, que trazem a morte, e que lançarei para vos destruir, aumentarei a fome sobre vós e quebrarei o sustento do pão;"},
{v:17,t:"mandarei contra vós a fome e as feras, que te deixarão sem filhos; a peste e o sangue passarão por ti, e farei vir a espada sobre ti. Eu, o Senhor, falei."}
];

window.TEXTOS_SEED["ezequiel"][6] = [
{s:"Contra os montes de Israel"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,t:"Filho do homem, volta o rosto para os montes de Israel e profetiza contra eles."},
{v:3,t:"Dize: Montes de Israel, ouvi a palavra do Senhor Deus. Assim diz o Senhor Deus aos montes e às colinas, às ravinas e aos vales: Eis que vou fazer vir sobre vós a espada e destruirei os vossos lugares altos;"},
{v:4,t:"os vossos altares serão demolidos, os vossos altares de incenso serão quebrados, e farei cair os vossos mortos diante dos vossos ídolos.",n:"Ídolos: em hebraico, gillulim, termo de desprezo muito usado por Ezequiel, talvez ligado a bolotas de esterco."},
{v:5,t:"Porei os cadáveres dos filhos de Israel diante dos seus ídolos e espalharei os vossos ossos ao redor dos vossos altares."},
{v:6,t:"Em todos os lugares onde morais, as cidades ficarão desertas e os lugares altos serão demolidos, para que os vossos altares sejam arrasados e destruídos, os vossos ídolos quebrados e eliminados, os vossos altares de incenso despedaçados e as vossas obras apagadas."},
{v:7,t:"Os mortos cairão no meio de vós, e sabereis que eu sou o Senhor."},
{v:8,t:"Mas deixarei entre vós alguns que escaparão da espada entre as nações, quando eu vos dispersar pelos países;",np:1},
{v:9,t:"e os vossos sobreviventes se lembrarão de mim entre as nações para onde tiverem sido levados cativos, porque eu quebrarei o seu coração adúltero, que se afastou de mim, e os seus olhos, que se prostituíram atrás dos seus ídolos; e terão nojo de si mesmos por causa das maldades que cometeram com todas as suas abominações,"},
{v:10,t:"e saberão que eu, o Senhor, não falei em vão, quando disse que lhes faria este mal."},
{s:"Lamento sobre as abominações"},
{v:11,t:"Assim diz o Senhor Deus: Bate palmas, bate com o pé e dize: Ai de todas as horríveis abominações da casa de Israel, que cairá pela espada, pela fome e pela peste!"},
{v:12,t:"Quem estiver longe morrerá de peste; quem estiver perto cairá pela espada; e quem sobreviver e estiver sitiado morrerá de fome; assim esgotarei neles o meu furor."},
{v:13,t:"E sabereis que eu sou o Senhor, quando os seus mortos jazerem no meio dos seus ídolos, ao redor dos seus altares, em toda colina elevada, em todos os cumes dos montes, debaixo de toda árvore frondosa e de todo carvalho copado, lugares onde ofereciam incenso perfumado a todos os seus ídolos."},
{v:14,t:"Estenderei a minha mão contra eles e farei da terra uma desolação e um deserto, desde o deserto até Rebla, em todos os lugares onde moram; e saberão que eu sou o Senhor.",n:"Rebla: assim a Nova Vulgata, com alguns manuscritos; o hebraico diz Dibla. O deserto fica no extremo sul, e Rebla, no extremo norte."}
];

window.TEXTOS_SEED["ezequiel"][7] = [
{s:"O fim chegou"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,t:"E tu, filho do homem, fala. Assim diz o Senhor Deus à terra de Israel: O fim! Chegou o fim sobre os quatro cantos da terra!"},
{v:3,t:"Agora o fim está sobre ti: lançarei contra ti a minha ira, eu te julgarei segundo os teus caminhos e farei cair sobre ti todas as tuas abominações."},
{v:4,t:"O meu olho não terá piedade de ti, e não terei compaixão; mas farei cair sobre ti os teus caminhos, e as tuas abominações estarão no meio de ti; e sabereis que eu sou o Senhor.",np:1},
{v:5,t:"Assim diz o Senhor Deus: Eis que vem desgraça após desgraça.",np:1},
{v:6,t:"Chegou o fim, chegou o fim; ele despertou contra ti; eis que chegou.",n:"No hebraico, jogo de palavras entre o fim (qets) e despertar (heqits)."},
{v:7,t:"Chegou para ti a ruína, habitante da terra; chegou o tempo, está perto o dia do tumulto, e não dos gritos de alegria nos montes.",n:"A ruína: palavra hebraica de sentido incerto."},
{v:8,t:"Agora, bem depressa, derramarei sobre ti a minha ira e esgotarei em ti o meu furor; eu te julgarei segundo os teus caminhos e farei cair sobre ti todas as tuas abominações;"},
{v:9,t:"o meu olho não terá piedade, e não terei compaixão; farei cair sobre ti os teus caminhos, e as tuas abominações estarão no meio de ti; e sabereis que sou eu, o Senhor, quem fere."},
{s:"O dia da ira"},
{v:10,t:"Eis o dia, eis que chega! Saiu a ruína, floresceu a injustiça, brotou o orgulho;"},
{v:11,t:"a violência se levantou como vara da impiedade; nada restará deles, nem da sua multidão, nem do seu tumulto, e não haverá descanso para eles."},
{v:12,t:"Chegou o tempo, aproximou-se o dia: quem compra não se alegre, e quem vende não se lamente, pois a ira está sobre toda a sua multidão."},
{v:13,t:"Pois quem vende não recuperará o que vendeu, ainda que continue vivo. Porque a visão contra toda a sua multidão não será revogada, e ninguém, por causa da sua iniquidade, conservará a vida.",n:"Alusão à lei do jubileu (Levítico 25,13–16): não haverá mais volta à propriedade de família."},
{v:14,t:"Tocai a trombeta, preparai tudo! Mas ninguém vai à batalha, pois a minha ira está sobre toda a sua multidão."},
{v:15,t:"Fora, a espada; dentro, a peste e a fome. Quem estiver no campo morrerá pela espada, e quem estiver na cidade será devorado pela fome e pela peste.",np:1},
{v:16,t:"Os que dentre eles escaparem se salvarão e estarão nos montes, como as pombas dos vales, todos gemendo, cada um pela sua iniquidade."},
{s:"O desespero do povo"},
{v:17,t:"Todas as mãos desfalecerão, e todos os joelhos se desfarão em água.",n:"Expressão do pavor extremo; alguns entendem que se urinarão de medo."},
{v:18,t:"Vestirão pano de saco, e o terror os cobrirá; haverá vergonha em todos os rostos e calvície em todas as cabeças."},
{v:19,t:"Jogarão a sua prata nas ruas, e o seu ouro se tornará imundície; a sua prata e o seu ouro não poderão salvá-los no dia do furor do Senhor; não saciarão a sua fome nem encherão o seu ventre, pois isso foi para eles ocasião de pecado,"},
{v:20,t:"e com o esplendor dos seus enfeites alimentaram o seu orgulho e fizeram deles as imagens das suas abominações e dos seus ídolos; por isso farei que isso se torne para eles imundície."},
{v:21,t:"Eu o entregarei como saque nas mãos dos estrangeiros e como presa aos ímpios da terra, que o profanarão."},
{v:22,t:"Desviarei deles o meu rosto, e profanarão o meu tesouro escondido; entrarão nele os salteadores e o profanarão,",n:"O meu tesouro escondido: o templo."},
{v:23,t:"e farão correntes; pois a terra está cheia de crimes de sangue, e a cidade, cheia de violência."},
{v:24,t:"Trarei as piores das nações, e elas possuirão as suas casas; porei fim ao orgulho dos poderosos, e eles possuirão os seus santuários."},
{v:25,t:"Chegará a angústia; procurarão a paz, e não haverá."},
{v:26,t:"Virá desgraça sobre desgraça, e boato sobre boato; pedirão uma visão ao profeta, mas a lei faltará ao sacerdote, e o conselho, aos anciãos."},
{v:27,t:"O rei ficará de luto, o príncipe se vestirá de desolação, e as mãos do povo da terra tremerão. Eu os tratarei segundo o seu procedimento e os julgarei segundo os seus próprios julgamentos; e saberão que eu sou o Senhor."}
];

window.TEXTOS_SEED["ezequiel"][8] = [
{s:"As abominações no templo"},
{v:1,t:"No sexto ano, no sexto mês, no dia cinco do mês, eu estava sentado em minha casa, e os anciãos de Judá estavam sentados diante de mim; e ali a mão do Senhor Deus caiu sobre mim.",n:"Em setembro de 592 antes de Cristo."},
{v:2,t:"Olhei, e eis uma figura com aparência de homem: desde o que parecia ser a sua cintura para baixo, era fogo; e desde a cintura para cima, algo como um esplendor, como o brilho do electro.",n:"Homem: assim a Nova Vulgata, com a tradução grega; o hebraico diz fogo."},
{v:3,t:"Ele estendeu algo semelhante a uma mão e me pegou por uma mecha de cabelo; e o espírito me levantou entre a terra e o céu e me levou a Jerusalém, em visões de Deus, à entrada da porta interior que dá para o norte, onde estava colocado o ídolo do ciúme, que provoca o ciúme.",n:"O ídolo do ciúme: talvez uma imagem de Aserá (compare 2 Reis 21,7), que provocava o ciúme do Senhor."},
{v:4,t:"E eis que ali estava a glória do Deus de Israel, como na visão que eu tinha tido na planície;"},
{v:5,t:"e ele me disse: Filho do homem, levanta os olhos na direção do norte. Levantei os olhos na direção do norte, e eis que, ao norte da porta do altar, estava aquele ídolo do ciúme, na entrada."},
{v:6,t:"E me disse: Filho do homem, vês o que eles fazem? As grandes abominações que a casa de Israel pratica aqui, para que eu me afaste do meu santuário? Mas verás ainda abominações maiores."},
{v:7,t:"Ele me levou à entrada do átrio, e olhei: eis que havia um buraco na parede.",np:1},
{v:8,t:"Ele me disse: Filho do homem, cava a parede. Cavei a parede, e apareceu uma porta."},
{v:9,t:"E me disse: Entra e vê as horríveis abominações que eles praticam aqui."},
{v:10,t:"Entrei e olhei: eis toda espécie de figuras de répteis e de animais abomináveis, e todos os ídolos da casa de Israel, pintados na parede, ao redor, por toda parte;"},
{v:11,t:"e setenta homens dos anciãos da casa de Israel, com Jezonias, filho de Safã, de pé no meio deles, estavam diante das pinturas, cada um com o seu incensório na mão, e subia a fumaça perfumada do incenso."},
{v:12,t:"Ele me disse: Viste, filho do homem, o que os anciãos da casa de Israel fazem nas trevas, cada um na sala da sua imagem? Pois dizem: O Senhor não nos vê; o Senhor abandonou a terra."},
{v:13,t:"E me disse: Verás ainda abominações maiores que eles praticam."},
{v:14,t:"Ele me levou à entrada da porta da casa do Senhor que dá para o norte, e eis que ali estavam sentadas mulheres chorando Tamuz.",np:1,n:"Tamuz: divindade babilônica da vegetação, cuja morte anual era chorada pelas mulheres."},
{v:15,t:"Ele me disse: Viste, filho do homem? Verás ainda abominações maiores do que estas."},
{v:16,t:"Ele me levou ao átrio interior da casa do Senhor, e eis que, à entrada do templo do Senhor, entre o vestíbulo e o altar, havia uns vinte e cinco homens, de costas para o templo do Senhor e com o rosto voltado para o oriente: adoravam o sol, voltados para o oriente.",np:1},
{v:17,t:"Ele me disse: Viste, filho do homem? Será pouca coisa para a casa de Judá praticar as abominações que praticam aqui? Pois encheram a terra de violência e voltaram a me provocar; e eis que levam o ramo ao nariz.",n:"Gesto de culto pagão, de sentido desconhecido."},
{v:18,t:"Por isso também eu agirei com furor: o meu olho não terá piedade, e não terei compaixão; e, ainda que gritem aos meus ouvidos em alta voz, não os escutarei."}
];

window.TEXTOS_SEED["ezequiel"][9] = [
{s:"O sinal na fronte e o castigo da cidade"},
{v:1,t:"Então ele gritou aos meus ouvidos em alta voz: Aproximam-se os castigos da cidade; cada um tenha na mão a sua arma de destruição."},
{v:2,t:"E eis que seis homens vinham pelo caminho da porta superior, que dá para o norte, cada um com a sua arma de destruição na mão; no meio deles havia um homem vestido de linho, com um estojo de escriba à cintura. Entraram e ficaram de pé junto do altar de bronze."},
{v:3,t:"A glória do Deus de Israel se elevou de cima do querubim sobre o qual estava e foi até o limiar do templo; e chamou o homem vestido de linho, que tinha o estojo de escriba à cintura."},
{v:4,t:"O Senhor lhe disse: Passa pelo meio da cidade, pelo meio de Jerusalém, e marca com um tau a fronte dos homens que gemem e se lamentam por todas as abominações que se praticam no meio dela.",n:"Tau: a última letra do alfabeto hebraico, que na escrita antiga tinha a forma de uma cruz. Os Padres da Igreja viram nela o sinal da cruz; compare Apocalipse 7,3."},
{v:5,t:"E aos outros disse, enquanto eu ouvia: Passai pela cidade atrás dele e feri; o vosso olho não tenha piedade, e não tenhais compaixão:"},
{v:6,t:"matai velhos, jovens e moças, crianças e mulheres, até exterminá-los; mas não toqueis em ninguém que tenha o tau. Começai pelo meu santuário. Começaram, então, pelos anciãos que estavam diante do templo.",n:"Nota do tradutor: a visão descreve o julgamento de Deus sobre a cidade culpada com a linguagem das guerras antigas; o texto não foi suavizado. O julgamento começa pelo santuário (compare 1 Pedro 4,17)."},
{v:7,t:"E lhes disse: Profanai o templo e enchei os átrios de mortos. Saí! Eles saíram e começaram a matar na cidade."},
{v:8,t:"Enquanto matavam, eu fiquei sozinho; caí com o rosto por terra e gritei: Ah, Senhor Deus! Vais destruir todo o resto de Israel, derramando o teu furor sobre Jerusalém?",np:1},
{v:9,t:"Ele me respondeu: A iniquidade da casa de Israel e de Judá é imensamente grande; a terra está cheia de sangue, e a cidade, cheia de injustiça. Pois dizem: O Senhor abandonou a terra, e o Senhor não vê."},
{v:10,t:"Por isso também o meu olho não terá piedade, e não terei compaixão: farei cair sobre a cabeça deles o seu procedimento."},
{v:11,t:"E eis que o homem vestido de linho, que tinha o estojo de escriba à cintura, veio dar conta, dizendo: Fiz como me ordenaste."}
];

window.TEXTOS_SEED["ezequiel"][10] = [
{s:"A glória do Senhor deixa o templo"},
{v:1,t:"Olhei, e eis que sobre o firmamento que estava acima da cabeça dos querubins apareceu algo como pedra de safira, algo semelhante a um trono."},
{v:2,t:"E o Senhor disse ao homem vestido de linho: Entra no meio das rodas, debaixo do querubim, enche as mãos de brasas de fogo que estão entre os querubins e espalha-as sobre a cidade. E ele entrou diante dos meus olhos.",np:1},
{v:3,t:"Os querubins estavam do lado direito do templo quando o homem entrou, e a nuvem encheu o átrio interior.",np:1},
{v:4,t:"A glória do Senhor se elevou de cima do querubim em direção ao limiar do templo; o templo se encheu da nuvem, e o átrio ficou cheio do esplendor da glória do Senhor."},
{v:5,t:"O ruído das asas dos querubins se ouvia até o átrio exterior, como a voz do Deus todo-poderoso quando fala."},
{v:6,t:"Quando o Senhor ordenou ao homem vestido de linho: Toma fogo do meio das rodas, do meio dos querubins, ele entrou e ficou de pé junto de uma roda;",np:1},
{v:7,t:"e um querubim estendeu a mão, do meio dos querubins, para o fogo que estava entre os querubins, tomou dele e o pôs nas mãos do homem vestido de linho, que o recebeu e saiu."},
{v:8,t:"Apareceu nos querubins algo semelhante a uma mão humana debaixo das suas asas,"},
{v:9,t:"e olhei: eis que havia quatro rodas ao lado dos querubins, uma roda ao lado de cada querubim; e o aspecto das rodas era como o brilho da pedra de crisólito;"},
{v:10,t:"quanto ao seu aspecto, as quatro tinham a mesma forma, como se uma roda estivesse dentro da outra."},
{v:11,t:"Quando se moviam, iam nas quatro direções, sem se voltarem ao andar; mas para onde se dirigia a primeira, as outras a seguiam, sem se voltarem ao andar."},
{v:12,t:"Todo o seu corpo, as costas, as mãos, as asas e as rodas estavam cheios de olhos ao redor, nas quatro."},
{v:13,t:"Quanto às rodas, ouvi que as chamavam: Turbilhão."},
{v:14,t:"Cada um tinha quatro faces: a primeira era face de querubim, a segunda, face de homem, a terceira, face de leão, e a quarta, face de águia.",n:"Face de querubim: em 1,10 é face de touro."},
{v:15,t:"E os querubins se elevaram: eram os mesmos seres vivos que eu tinha visto junto ao rio Cobar."},
{v:16,t:"Quando os querubins andavam, as rodas andavam ao lado deles; e quando os querubins levantavam as asas para se elevar da terra, as rodas não se afastavam deles, mas permaneciam ao seu lado."},
{v:17,t:"Quando eles paravam, elas paravam; e quando se elevavam, elas se elevavam com eles; pois o espírito dos seres vivos estava nelas."},
{v:18,t:"A glória do Senhor saiu de sobre o limiar do templo e parou sobre os querubins;",np:1},
{v:19,t:"os querubins levantaram as asas e se elevaram da terra diante dos meus olhos; saíram, e as rodas com eles; e pararam à entrada da porta oriental da casa do Senhor; e a glória do Deus de Israel estava sobre eles, no alto."},
{v:20,t:"Eram os mesmos seres vivos que eu tinha visto debaixo do Deus de Israel, junto ao rio Cobar, e reconheci que eram querubins."},
{v:21,t:"Cada um tinha quatro faces e cada um tinha quatro asas, e debaixo das asas havia algo semelhante a mãos humanas;"},
{v:22,t:"e as suas faces eram semelhantes às faces que eu tinha visto junto ao rio Cobar. Cada um andava para a frente."}
];

window.TEXTOS_SEED["ezequiel"][11] = [
{s:"Contra os chefes do povo"},
{v:1,t:"O espírito me levantou e me levou à porta oriental da casa do Senhor, a que dá para o nascer do sol; e eis que à entrada da porta havia vinte e cinco homens, e vi no meio deles Jezonias, filho de Azur, e Feltias, filho de Banaías, chefes do povo."},
{v:2,t:"Ele me disse: Filho do homem, estes são os homens que tramam a iniquidade e dão maus conselhos nesta cidade,"},
{v:3,t:"dizendo: Não foi há pouco tempo que se construíram as casas? A cidade é a panela, e nós somos a carne.",n:"Os que ficaram em Jerusalém se consideravam a parte escolhida, protegida como a carne dentro da panela."},
{v:4,t:"Por isso profetiza contra eles; profetiza, filho do homem."},
{v:5,t:"O espírito do Senhor caiu sobre mim e me disse: Fala. Assim diz o Senhor: É assim que falais, casa de Israel, e eu conheço os pensamentos do vosso coração."},
{v:6,t:"Multiplicastes os mortos nesta cidade e enchestes as suas ruas de cadáveres."},
{v:7,t:"Por isso assim diz o Senhor Deus: Os mortos que deixastes no meio dela, eles são a carne, e ela é a panela; mas a vós eu farei sair do meio dela."},
{v:8,t:"Temeis a espada, e é a espada que farei vir sobre vós, oráculo do Senhor Deus."},
{v:9,t:"Eu vos farei sair do meio dela, vos entregarei nas mãos de estrangeiros e executarei em vós os meus julgamentos."},
{v:10,t:"Caireis pela espada; eu vos julgarei nas fronteiras de Israel, e sabereis que eu sou o Senhor.",n:"Cumpriu-se em Rebla (2 Reis 25,18–21)."},
{v:11,t:"A cidade não será para vós uma panela, nem vós sereis a carne dentro dela: eu vos julgarei nas fronteiras de Israel;"},
{v:12,t:"e sabereis que eu sou o Senhor, cujos preceitos não seguistes e cujos decretos não cumpristes, mas agistes segundo os costumes das nações que vos rodeiam."},
{v:13,t:"Enquanto eu profetizava, Feltias, filho de Banaías, morreu. Caí com o rosto por terra e gritei em alta voz: Ah, Senhor Deus! Vais exterminar o resto de Israel?",np:1},
{s:"Um coração novo para os exilados"},
{v:14,t:"A palavra do Senhor me foi dirigida:"},
{v:15,t:"Filho do homem, os teus irmãos, os teus irmãos, os homens da tua parentela e toda a casa de Israel, todos eles, são aqueles de quem os habitantes de Jerusalém disseram: Estão longe do Senhor; é a nós que esta terra foi dada em propriedade."},
{v:16,t:"Por isso assim diz o Senhor Deus: Sim, eu os afastei para longe entre as nações e os dispersei pelos países; mas eu mesmo serei para eles, por pouco tempo, um santuário nos países para onde foram.",n:"Por pouco tempo: ou, em pequena medida. Deus está presente também no exílio, sem templo."},
{v:17,t:"Por isso dize: Assim diz o Senhor Deus: Eu vos reunirei dentre os povos, vos juntarei dos países para onde fostes dispersos e vos darei a terra de Israel."},
{v:18,t:"Eles voltarão para lá e tirarão dela todas as suas coisas detestáveis e todas as suas abominações."},
{v:19,t:"Eu lhes darei outro coração e porei no seu íntimo um espírito novo; tirarei do seu corpo o coração de pedra e lhes darei um coração de carne,",n:"Outro coração: assim a Nova Vulgata, com a tradução grega; o hebraico diz: um só coração. Compare 36,26–27; Jeremias 31,33."},
{v:20,t:"para que andem nos meus preceitos, guardem os meus decretos e os cumpram; eles serão o meu povo, e eu serei o seu Deus."},
{v:21,t:"Mas aqueles cujo coração segue as suas coisas detestáveis e as suas abominações, farei cair sobre a cabeça deles o seu procedimento, oráculo do Senhor Deus.",np:1},
{s:"A glória do Senhor deixa a cidade"},
{v:22,t:"Os querubins levantaram as asas, e as rodas com eles; e a glória do Deus de Israel estava sobre eles, no alto."},
{v:23,t:"A glória do Senhor se elevou do meio da cidade e parou sobre o monte que está a oriente da cidade.",n:"O monte das Oliveiras. Em 43,1–5 a glória voltará pelo mesmo caminho."},
{v:24,t:"O espírito me levantou e me levou à Caldeia, aos deportados, em visão, pelo espírito de Deus; e a visão que eu tinha tido se afastou de mim.",np:1},
{v:25,t:"E contei aos deportados todas as palavras que o Senhor me tinha mostrado."}
];

window.TEXTOS_SEED["ezequiel"][12] = [
{s:"A bagagem do exilado"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,t:"Filho do homem, tu moras no meio de uma casa rebelde, que tem olhos para ver e não vê, ouvidos para ouvir e não ouve, porque é uma casa rebelde."},
{v:3,t:"Tu, pois, filho do homem, prepara a bagagem de exilado e parte de dia, diante dos seus olhos; partirás do lugar onde estás para outro lugar, diante dos seus olhos; talvez vejam, pois são uma casa rebelde."},
{v:4,t:"Levarás para fora a tua bagagem, como bagagem de exilado, de dia, diante dos seus olhos; e tu sairás à tarde, diante deles, como sai quem vai para o exílio."},
{v:5,t:"Diante dos seus olhos, abre um buraco na parede e sai por ele levando a bagagem;"},
{v:6,t:"diante deles, tu a carregarás nos ombros e sairás na escuridão; cobrirás o rosto, para não ver a terra, pois fiz de ti um sinal para a casa de Israel."},
{v:7,t:"Fiz como o Senhor me tinha ordenado: levei para fora de dia a minha bagagem, como bagagem de exilado; à tarde, abri com a mão um buraco na parede e saí na escuridão, carregando-a nos ombros diante dos seus olhos.",np:1},
{v:8,t:"De manhã, a palavra do Senhor me foi dirigida:",np:1},
{v:9,t:"Filho do homem, a casa de Israel, essa casa rebelde, não te perguntou: Que estás fazendo?"},
{v:10,t:"Dize-lhes: Assim diz o Senhor Deus: Este oráculo diz respeito ao príncipe que está em Jerusalém e a toda a casa de Israel que está nela.",n:"Oráculo: em hebraico, massá, que significa também carga; jogo de palavras com a bagagem que o profeta carrega. O príncipe é o rei Sedecias."},
{v:11,t:"Dize: Eu sou para vós um sinal. Como eu fiz, assim lhes será feito: irão para o exílio, para o cativeiro."},
{v:12,t:"O príncipe que está no meio deles carregará a bagagem nos ombros, na escuridão, e sairá; abrirão um buraco na parede para passar por ele; ele cobrirá o rosto, para não ver a terra com os olhos.",n:"Compare a fuga de Sedecias (2 Reis 25,4–7; Jeremias 39,4–7)."},
{v:13,t:"Estenderei sobre ele a minha rede, e ele será apanhado no meu laço; eu o levarei para a Babilônia, à terra dos caldeus; mas ele não a verá, e lá morrerá.",n:"Sedecias foi cegado antes de ser levado à Babilônia (2 Reis 25,7)."},
{v:14,t:"Todos os que o rodeiam, a sua guarda e todas as suas tropas, eu os espalharei a todos os ventos e desembainharei a espada atrás deles."},
{v:15,t:"E saberão que eu sou o Senhor, quando os dispersar entre as nações e os espalhar pelos países."},
{v:16,t:"Mas deixarei alguns deles escapar da espada, da fome e da peste, para que contem todas as suas abominações entre as nações para onde forem; e saberão que eu sou o Senhor."},
{s:"O pão comido com tremor"},
{v:17,t:"A palavra do Senhor me foi dirigida:"},
{v:18,t:"Filho do homem, come o teu pão com tremor e bebe a tua água com angústia e inquietação."},
{v:19,t:"E dirás ao povo da terra: Assim diz o Senhor Deus aos habitantes de Jerusalém, na terra de Israel: Comerão o seu pão com inquietação e beberão a sua água com espanto, porque a sua terra será despojada de tudo o que a enche, por causa da violência de todos os que nela habitam;"},
{v:20,t:"as cidades habitadas serão devastadas, e a terra se tornará um deserto; e sabereis que eu sou o Senhor."},
{s:"As visões se cumprirão"},
{v:21,t:"A palavra do Senhor me foi dirigida:"},
{v:22,t:"Filho do homem, que provérbio é este que tendes na terra de Israel: Os dias se prolongam, e toda visão falha?"},
{v:23,t:"Por isso dize-lhes: Assim diz o Senhor Deus: Farei cessar este provérbio, e não se repetirá mais em Israel. Dize-lhes antes: Estão próximos os dias e o cumprimento de toda visão."},
{v:24,t:"Pois não haverá mais visão vazia nem adivinhação enganosa no meio da casa de Israel,"},
{v:25,t:"porque eu, o Senhor, falarei; a palavra que eu disser se cumprirá, e não será mais adiada; mas nos vossos dias, casa rebelde, direi uma palavra e a cumprirei, oráculo do Senhor Deus."},
{v:26,t:"A palavra do Senhor me foi dirigida:",np:1},
{v:27,t:"Filho do homem, eis que a casa de Israel diz: A visão que este homem tem é para dias distantes, e ele profetiza para tempos longínquos."},
{v:28,t:"Por isso dize-lhes: Assim diz o Senhor Deus: Nenhuma das minhas palavras será mais adiada; a palavra que eu disser se cumprirá, oráculo do Senhor Deus."}
];

window.TEXTOS_SEED["ezequiel"][13] = [
{s:"Contra os falsos profetas"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,t:"Filho do homem, profetiza contra os profetas de Israel que profetizam, e dize aos que profetizam segundo o seu próprio coração: Ouvi a palavra do Senhor."},
{v:3,t:"Assim diz o Senhor Deus: Ai dos profetas insensatos, que seguem o seu próprio espírito, sem terem visto nada!"},
{v:4,t:"Os teus profetas, Israel, são como raposas no meio das ruínas."},
{v:5,t:"Não subistes às brechas, nem levantastes um muro em defesa da casa de Israel, para resistir no combate, no dia do Senhor."},
{v:6,t:"Têm visões vazias e adivinhações mentirosas; dizem: Oráculo do Senhor, sem que o Senhor os tenha enviado, e ainda esperam que ele confirme a sua palavra.",np:1},
{v:7,t:"Não é verdade que tivestes visões vazias e anunciastes adivinhações mentirosas, quando dizeis: Oráculo do Senhor, sem que eu tenha falado?"},
{v:8,t:"Por isso assim diz o Senhor Deus: Porque dissestes coisas vazias e tivestes visões mentirosas, eis que estou contra vós, oráculo do Senhor Deus;",np:1},
{v:9,t:"a minha mão estará contra os profetas que têm visões vazias e adivinhações mentirosas: não farão parte do conselho do meu povo, não serão inscritos no registro da casa de Israel e não entrarão na terra de Israel; e sabereis que eu sou o Senhor Deus."},
{v:10,t:"Porque enganaram o meu povo, dizendo: Paz, quando não há paz; e, quando o povo constrói um muro, eles o rebocam com cal."},
{v:11,t:"Dize aos que o rebocam com cal que ele cairá: virá uma chuva torrencial, farei cair pedras de granizo, e se desencadeará um vento de tempestade."},
{v:12,t:"E eis que o muro caiu; não vos perguntarão: Onde está o reboco com que o rebocastes?"},
{v:13,t:"Por isso assim diz o Senhor Deus: Na minha ira farei irromper um vento de tempestade; na minha cólera virá uma chuva torrencial, e, no meu furor, pedras de granizo para destruir;"},
{v:14,t:"derrubarei o muro que rebocastes com cal e o deitarei por terra, de modo que os seus alicerces ficarão descobertos; ele cairá, e vós perecereis debaixo dele; e sabereis que eu sou o Senhor."},
{v:15,t:"Esgotarei o meu furor contra o muro e contra os que o rebocaram com cal, e vos direi: Não existe mais o muro, nem os que o rebocaram;",np:1},
{v:16,t:"os profetas de Israel, que profetizavam a respeito de Jerusalém e tinham para ela visões de paz, quando não havia paz, oráculo do Senhor Deus."},
{s:"Contra as falsas profetisas"},
{v:17,t:"E tu, filho do homem, volta o rosto contra as filhas do teu povo, que profetizam segundo o seu próprio coração, e profetiza contra elas,"},
{v:18,t:"e dize: Assim diz o Senhor Deus: Ai das que costuram faixas para todos os pulsos e fazem véus para cabeças de todas as alturas, para caçar vidas! Caçareis as vidas do meu povo e conservareis a vida para vós mesmas?",n:"Práticas de magia, de sentido não totalmente claro."},
{v:19,t:"Vós me desonrastes diante do meu povo por um punhado de cevada e por um pedaço de pão, fazendo morrer os que não deviam morrer e fazendo viver os que não deviam viver, mentindo ao meu povo, que dá ouvidos à mentira."},
{v:20,t:"Por isso assim diz o Senhor Deus: Eis que estou contra as vossas faixas, com as quais caçais as vidas como pássaros; eu as arrancarei dos vossos braços e soltarei as vidas que caçais como pássaros.",np:1},
{v:21,t:"Rasgarei os vossos véus e livrarei o meu povo das vossas mãos, e eles não serão mais presa nas vossas mãos; e sabereis que eu sou o Senhor."},
{v:22,t:"Porque entristecestes com mentiras o coração do justo, que eu não quis entristecer, e fortalecestes as mãos do ímpio, para que não se convertesse do seu mau caminho e vivesse,",np:1},
{v:23,t:"por isso não tereis mais visões vazias, nem praticareis mais adivinhações; livrarei o meu povo das vossas mãos, e sabereis que eu sou o Senhor."}
];

window.TEXTOS_SEED["ezequiel"][14] = [
{s:"Os idólatras que consultam o profeta"},
{v:1,t:"Alguns dos anciãos de Israel vieram ter comigo e se sentaram diante de mim."},
{v:2,t:"A palavra do Senhor me foi dirigida:"},
{v:3,t:"Filho do homem, estes homens puseram os seus ídolos no coração e colocaram diante dos olhos aquilo que os faz cair na iniquidade; deverei eu responder-lhes quando me consultam?"},
{v:4,t:"Por isso fala-lhes e dize-lhes: Assim diz o Senhor Deus: Todo homem da casa de Israel que puser os seus ídolos no coração, colocar diante dos olhos aquilo que o faz cair na iniquidade e vier ao profeta para me consultar por meio dele, eu, o Senhor, eu mesmo lhe responderei segundo a multidão dos seus ídolos,"},
{v:5,t:"para apanhar a casa de Israel no seu próprio coração, pois se afastou de mim por causa de todos os seus ídolos."},
{v:6,t:"Por isso dize à casa de Israel: Assim diz o Senhor Deus: Convertei-vos, afastai-vos dos vossos ídolos e desviai o rosto de todas as vossas abominações.",np:1},
{v:7,t:"Pois a todo homem da casa de Israel, ou dos estrangeiros que moram em Israel, que se afastar de mim, puser os seus ídolos no coração, colocar diante dos olhos aquilo que o faz cair na iniquidade e vier ao profeta para me consultar por meio dele, eu, o Senhor, eu mesmo lhe responderei;"},
{v:8,t:"voltarei o meu rosto contra esse homem, farei dele um exemplo e um provérbio e o exterminarei do meio do meu povo; e sabereis que eu sou o Senhor."},
{v:9,t:"Se o profeta se deixar enganar e disser alguma palavra, fui eu, o Senhor, que enganei esse profeta; estenderei a minha mão contra ele e o eliminarei do meio do meu povo Israel.",np:1,n:"Nota do tradutor: o texto atribui a Deus o engano do falso profeta, à maneira do Antigo Testamento, que remete tudo à causa primeira (compare 1 Reis 22,19–23); não foi suavizado."},
{v:10,t:"Ambos carregarão a sua iniquidade: a iniquidade do profeta será como a iniquidade de quem o consulta,"},
{v:11,t:"para que a casa de Israel não se afaste mais de mim e não se contamine mais com todas as suas transgressões; mas seja o meu povo, e eu seja o seu Deus, oráculo do Senhor Deus."},
{s:"Noé, Danel e Jó"},
{v:12,t:"A palavra do Senhor me foi dirigida:"},
{v:13,t:"Filho do homem, se uma terra pecar contra mim, cometendo infidelidade, e eu estender a mão contra ela, quebrar o sustento do seu pão, mandar sobre ela a fome e exterminar dela homens e animais,"},
{v:14,t:"ainda que estivessem nela estes três homens, Noé, Danel e Jó, eles salvariam somente a própria vida por causa da sua justiça, oráculo do Senhor Deus.",n:"Danel: antigo sábio e justo, conhecido também de textos de Ugarit; provavelmente não é o Daniel do livro de Daniel. Compare 28,3."},
{v:15,t:"Se eu fizer passar pela terra feras terríveis, que a deixem sem filhos, e ela se tornar um deserto, por onde ninguém passe por causa das feras,"},
{v:16,t:"ainda que estivessem nela esses três homens, pela minha vida, oráculo do Senhor Deus, não salvariam nem filhos nem filhas; só eles seriam salvos, e a terra ficaria desolada."},
{v:17,t:"Ou, se eu fizer vir a espada contra essa terra, disser à espada que passe pela terra e exterminar dela homens e animais,"},
{v:18,t:"ainda que estivessem nela esses três homens, pela minha vida, oráculo do Senhor Deus, não salvariam nem filhos nem filhas; só eles seriam salvos."},
{v:19,t:"Ou, se eu mandar a peste contra essa terra e derramar sobre ela o meu furor com sangue, para exterminar dela homens e animais,"},
{v:20,t:"ainda que estivessem nela Noé, Danel e Jó, pela minha vida, oráculo do Senhor Deus, não salvariam nem filho nem filha; por causa da sua justiça, salvariam somente a própria vida."},
{v:21,t:"Pois assim diz o Senhor Deus: Ainda que eu mande contra Jerusalém os meus quatro castigos terríveis, a espada, a fome, as feras e a peste, para exterminar dela homens e animais,",np:1},
{v:22,t:"ainda assim ficarão nela alguns sobreviventes, filhos e filhas que serão levados para fora; eis que eles virão até vós, e vereis o seu procedimento e as suas obras, e vos consolareis da desgraça que fiz cair sobre Jerusalém, de tudo o que fiz cair sobre ela."},
{v:23,t:"Eles vos consolarão, quando virdes o seu procedimento e as suas obras, e reconhecereis que não foi sem motivo que fiz tudo o que fiz nela, oráculo do Senhor Deus."}
];

window.TEXTOS_SEED["ezequiel"][15] = [
{s:"A videira inútil"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,l:["Filho do homem, em que é melhor a madeira da videira","do que qualquer ramo","entre as árvores do bosque?"],np:1},
{v:3,l:["Tira-se dela madeira","para fazer alguma obra?","Ou faz-se dela uma estaca","para pendurar algum utensílio?"],np:1},
{v:4,l:["Eis que foi lançada ao fogo para ser consumida;","o fogo consumiu as duas pontas,","e o meio ficou queimado;","servirá ainda para alguma obra?"],np:1},
{v:5,l:["Mesmo quando estava inteira,","não servia para nenhuma obra;","quanto menos agora, que o fogo a devorou e queimou,","se poderá fazer dela alguma obra!"],np:1},
{v:6,l:["Por isso assim diz o Senhor Deus:","Como a madeira da videira entre as árvores do bosque,","que eu entreguei ao fogo para ser consumida,","assim entregarei os habitantes de Jerusalém."],np:1},
{v:7,l:["Voltarei o rosto contra eles:","escaparam do fogo,","mas o fogo os devorará.","E sabereis que eu sou o Senhor,","quando voltar o rosto contra eles"],np:1},
{v:8,l:["e fizer da terra um lugar desolado e deserto,","porque foram infiéis,","oráculo do Senhor Deus."],np:1}
];

window.TEXTOS_SEED["ezequiel"][16] = [
{s:"A menina abandonada que o Senhor desposou"},
{v:1,t:"A palavra do Senhor me foi dirigida:",n:"Nota do tradutor: este capítulo descreve a infidelidade de Jerusalém com a imagem de uma esposa adúltera, em linguagem crua, própria dos profetas (compare Oseias 2; Jeremias 3); o texto não foi suavizado."},
{v:2,t:"Filho do homem, faze Jerusalém conhecer as suas abominações"},
{v:3,t:"e dize: Assim diz o Senhor Deus a Jerusalém: Pela tua origem e pelo teu nascimento, és da terra de Canaã; teu pai era amorreu, e tua mãe, heteia."},
{v:4,t:"Quanto ao teu nascimento, no dia em que nasceste, não te cortaram o cordão umbilical, não foste lavada com água para ficares limpa, não foste esfregada com sal, nem envolta em faixas."},
{v:5,t:"Nenhum olho teve piedade de ti para te fazer alguma destas coisas, por compaixão de ti; mas foste jogada em pleno campo, desprezada, no dia em que nasceste."},
{v:6,t:"Passei junto de ti e vi que te debatias no teu sangue, e te disse, quando estavas no teu sangue: Vive! Sim, eu te disse: Vive no teu sangue!",np:1},
{v:7,t:"Eu te fiz crescer como a erva do campo; cresceste, ficaste grande e chegaste à idade da beleza: os teus seios se formaram, e o teu cabelo cresceu; mas estavas nua e cheia de vergonha."},
{v:8,t:"Passei junto de ti e te vi: eis que era o teu tempo, o tempo dos amores. Estendi sobre ti a barra do meu manto e cobri a tua nudez; fiz-te um juramento e entrei em aliança contigo, oráculo do Senhor Deus, e passaste a ser minha.",n:"Estender o manto sobre uma mulher era gesto de casamento (compare Rute 3,9)."},
{v:9,t:"Eu te lavei com água, limpei-te do teu sangue e te ungi com óleo;"},
{v:10,t:"vesti-te com roupas bordadas, calcei-te com sandálias de couro fino, cingi-te de linho fino e te cobri de seda."},
{v:11,t:"Enfeitei-te com joias, pus braceletes nos teus pulsos e um colar no teu pescoço;"},
{v:12,t:"pus uma argola no teu nariz, brincos nas tuas orelhas e uma coroa magnífica na tua cabeça."},
{v:13,t:"Ficaste enfeitada de ouro e de prata, e a tua roupa era de linho fino, de seda e de bordados. Comias flor de farinha, mel e azeite; tornaste-te extremamente bela e chegaste à realeza."},
{v:14,t:"A tua fama se espalhou entre as nações por causa da tua beleza, pois era perfeita, graças ao esplendor que eu tinha posto sobre ti, oráculo do Senhor Deus."},
{s:"A esposa infiel"},
{v:15,t:"Mas confiaste na tua beleza e te prostituíste, aproveitando-te da tua fama; ofereceste a tua prostituição a todo aquele que passava, fosse quem fosse."},
{v:16,t:"Tomaste das tuas roupas e fizeste para ti lugares altos enfeitados, e ali te prostituíste, como nunca aconteceu nem acontecerá."},
{v:17,t:"Tomaste as tuas joias magníficas, feitas do meu ouro e da minha prata, que eu te tinha dado, e fizeste para ti imagens de homens, com as quais te prostituíste."},
{v:18,t:"Tomaste as tuas roupas bordadas e as cobriste, e puseste diante delas o meu óleo e o meu incenso."},
{v:19,t:"O meu pão, que eu te tinha dado, a flor de farinha, o azeite e o mel com que eu te alimentava, tu o puseste diante delas como perfume agradável. Foi assim, oráculo do Senhor Deus."},
{v:20,t:"Tomaste os filhos e as filhas que me tinhas dado à luz e os sacrificaste a elas, para que fossem devorados. Era pouca coisa a tua prostituição?",np:1},
{v:21,t:"Imolaste os meus filhos e os entregaste, fazendo-os passar pelo fogo em honra delas."},
{v:22,t:"E, no meio de todas as tuas abominações e prostituições, não te lembraste dos dias da tua juventude, quando estavas nua e cheia de vergonha, debatendo-te no teu sangue."},
{v:23,t:"E, depois de toda a tua maldade — ai de ti, ai de ti, oráculo do Senhor Deus! —,",np:1},
{v:24,t:"construíste para ti um prostíbulo e fizeste para ti um lugar alto em todas as praças;"},
{v:25,t:"em todas as esquinas construíste o teu lugar alto, fizeste da tua beleza uma abominação, abriste as pernas a todo aquele que passava e multiplicaste as tuas prostituições."},
{v:26,t:"Tu te prostituíste com os egípcios, teus vizinhos de corpo avantajado, e multiplicaste as tuas prostituições para me irritar.",n:"Alusão às alianças políticas com o Egito, com a Assíria e com a Babilônia, vistas como infidelidade ao Senhor."},
{v:27,t:"Eis que estendi a minha mão contra ti, diminuí a tua porção e te entreguei à vontade das que te odeiam, as filhas dos filisteus, que se envergonharam da tua conduta infame."},
{v:28,t:"Tu te prostituíste com os assírios, porque ainda não estavas satisfeita; e, depois de te prostituíres com eles, nem assim ficaste satisfeita.",np:1},
{v:29,t:"Multiplicaste as tuas prostituições com a terra dos mercadores, a Caldeia, e nem assim ficaste satisfeita."},
{v:30,t:"Como purificarei o teu coração, oráculo do Senhor Deus, quando fazias todas essas coisas, obras de uma prostituta descarada?",n:"Assim a Nova Vulgata; o hebraico diz: Como é fraco o teu coração!"},
{v:31,t:"Construíste o teu prostíbulo em todas as esquinas e fizeste o teu lugar alto em todas as praças; mas não foste como uma prostituta, porque desprezaste o pagamento."},
{v:32,t:"A mulher adúltera, em lugar do marido, recebe os estranhos."},
{v:33,t:"A todas as prostitutas se paga; mas tu davas presentes a todos os teus amantes e os subornavas para que viessem de todos os lados prostituir-se contigo."},
{v:34,t:"Contigo aconteceu o contrário do que acontece com as outras mulheres nas suas prostituições: ninguém corria atrás de ti; tu davas o pagamento e não recebias pagamento; foste o contrário das outras.",np:1},
{s:"O castigo da adúltera"},
{v:35,t:"Por isso, prostituta, ouve a palavra do Senhor."},
{v:36,t:"Assim diz o Senhor Deus: Porque derramaste o teu dinheiro e descobriste a tua nudez nas tuas prostituições com os teus amantes e com todos os teus ídolos abomináveis, e por causa do sangue dos teus filhos que lhes deste,"},
{v:37,t:"por isso eis que vou reunir todos os teus amantes, com quem tiveste prazer, todos os que amaste e todos os que odiaste; eu os reunirei contra ti de todos os lados e descobrirei diante deles a tua nudez, e eles verão toda a tua vergonha."},
{v:38,t:"Eu te julgarei como se julgam as adúlteras e as assassinas e farei cair sobre ti o sangue do furor e do ciúme."},
{v:39,t:"Eu te entregarei nas mãos deles, e eles destruirão o teu prostíbulo, demolirão os teus lugares altos, tirarão as tuas roupas, levarão as tuas joias magníficas e te deixarão nua e coberta de vergonha."},
{v:40,t:"Convocarão contra ti uma assembleia, te apedrejarão e te despedaçarão com as suas espadas."},
{v:41,t:"Queimarão as tuas casas e executarão em ti os julgamentos à vista de muitas mulheres; porei fim à tua prostituição, e não darás mais pagamento."},
{v:42,t:"Saciarei em ti o meu furor, e o meu ciúme se afastará de ti; ficarei tranquilo e não me irritarei mais."},
{v:43,t:"Porque não te lembraste dos dias da tua juventude e me irritaste com todas essas coisas, também eu farei cair sobre a tua cabeça o teu procedimento, oráculo do Senhor Deus; e ainda não te tratei segundo os teus crimes, em todas as tuas abominações.",n:"Hebraico obscuro; a Nova Vulgata entende assim."},
{s:"Pior que Samaria e Sodoma"},
{v:44,t:"Eis que todos os que usam provérbios dirão de ti este provérbio: Tal mãe, tal filha."},
{v:45,t:"Tu és bem filha da tua mãe, que desprezou o marido e os filhos; és irmã das tuas irmãs, que desprezaram os seus maridos e os seus filhos. Vossa mãe era heteia, e vosso pai, amorreu."},
{v:46,t:"A tua irmã mais velha é Samaria, com as suas filhas, que mora à tua esquerda; e a tua irmã mais nova que tu, que mora à tua direita, é Sodoma, com as suas filhas.",n:"À esquerda, isto é, ao norte; à direita, ao sul. As filhas são as cidades dependentes."},
{v:47,t:"Não andaste nos caminhos delas, nem imitaste as suas abominações; como se isso fosse pouco, foste mais corrompida do que elas em todos os teus caminhos.",np:1},
{v:48,t:"Pela minha vida, oráculo do Senhor Deus, Sodoma, tua irmã, ela e as suas filhas, não fizeram o que fizeste tu e as tuas filhas."},
{v:49,t:"Eis qual foi a iniquidade de Sodoma, tua irmã: orgulho, fartura de pão e ociosidade tranquila tinham ela e as suas filhas; e não socorriam o pobre e o necessitado.",n:"Compare Gênesis 19."},
{v:50,t:"Tornaram-se altivas e cometeram abominações diante de mim; por isso as fiz desaparecer, como viste."},
{v:51,t:"Samaria não cometeu nem a metade dos teus pecados; tu multiplicaste as tuas abominações mais do que elas e fizeste as tuas irmãs parecerem justas com todas as abominações que cometeste."},
{v:52,t:"Carrega, pois, tu também a tua vergonha, tu que justificaste as tuas irmãs com os teus pecados, agindo de modo mais abominável do que elas; elas são mais justas do que tu. Envergonha-te, pois, também tu, e carrega a tua ignomínia, porque fizeste as tuas irmãs parecerem justas.",np:1},
{v:53,t:"Mudarei a sorte delas, a sorte de Sodoma e das suas filhas e a sorte de Samaria e das suas filhas; e mudarei a tua sorte no meio delas,"},
{v:54,t:"para que carregues a tua ignomínia e te envergonhes de tudo o que fizeste, sendo para elas motivo de consolo."},
{v:55,t:"A tua irmã Sodoma e as suas filhas voltarão ao seu estado antigo, Samaria e as suas filhas voltarão ao seu estado antigo, e tu e as tuas filhas voltareis ao vosso estado antigo."},
{v:56,t:"Não era Sodoma, tua irmã, objeto dos teus comentários no tempo do teu orgulho,"},
{v:57,t:"antes que fosse descoberta a tua maldade, como agora, que és objeto de insulto das filhas da Síria e de todas as suas vizinhas, as filhas dos filisteus, que te desprezam ao redor?"},
{v:58,t:"Tu carregas o teu crime e a tua ignomínia, oráculo do Senhor."},
{s:"A aliança eterna"},
{v:59,t:"Pois assim diz o Senhor Deus: Farei contigo como fizeste, tu que desprezaste o juramento, rompendo a aliança."},
{v:60,t:"Mas eu me lembrarei da aliança que fiz contigo nos dias da tua juventude e estabelecerei contigo uma aliança eterna.",np:1},
{v:61,t:"Tu te lembrarás dos teus caminhos e te envergonharás, quando receberes as tuas irmãs, as mais velhas e as mais novas, que eu te darei como filhas, mas não em virtude da tua aliança."},
{v:62,t:"Estabelecerei contigo a minha aliança, e saberás que eu sou o Senhor,"},
{v:63,t:"para que te lembres e te envergonhes, e, na tua confusão, não abras mais a boca, quando eu te tiver perdoado tudo o que fizeste, oráculo do Senhor Deus."}
];

window.TEXTOS_SEED["ezequiel"][17] = [
{s:"A parábola das águias e da videira"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,t:"Filho do homem, propõe um enigma e conta uma parábola à casa de Israel,"},
{v:3,l:["e dize:","Assim diz o Senhor Deus:","Uma grande águia,","de grandes asas,","de longas penas,","cheia de plumagem colorida,","veio ao Líbano","e tomou a copa do cedro;"]},
{v:4,l:["arrancou o mais alto dos seus ramos","e o levou para a terra de Canaã;","colocou-o numa cidade de comerciantes."],np:1,n:"A terra de Canaã: aqui, terra de comerciantes, isto é, a Babilônia (v. 12)."},
{v:5,l:["Depois tomou uma semente da terra","e a pôs num campo de semeadura,","junto de águas abundantes;","plantou-a como um salgueiro,"],np:1},
{v:6,l:["para que brotasse e se tornasse uma videira extensa,","de pouca altura,","com os ramos voltados para ela","e as raízes debaixo dela.","Tornou-se, pois, uma videira,","deu ramos","e estendeu os seus sarmentos."],np:1},
{v:7,l:["Mas havia outra grande águia,","de grandes asas","e de muita plumagem;","e eis que aquela videira,","como que lançando para ela as suas raízes,","estendeu para ela os seus ramos,","para que a regasse mais abundantemente","do que os canteiros onde estava plantada."],np:1},
{v:8,l:["Numa boa terra,","junto de águas abundantes,","estava plantada,","para produzir ramos,","dar fruto","e tornar-se uma videira magnífica."],np:1},
{v:9,l:["Dize: Assim diz o Senhor Deus:","Prosperará ela?","Não lhe arrancarão as raízes","e não lhe colherão os frutos?","Não secarão todos os brotos novos, e ela não murchará?","Não será preciso braço forte nem povo numeroso","para arrancá-la pela raiz."],np:1},
{v:10,l:["Eis que está plantada; prosperará ela?","Quando o vento abrasador a tocar,","não secará","e não murchará nos canteiros onde brotou?"],np:1},
{s:"Explicação da parábola"},
{v:11,t:"A palavra do Senhor me foi dirigida:"},
{v:12,t:"Dize a essa casa rebelde: Não sabeis o que significam estas coisas? Dize: Eis que o rei da Babilônia veio a Jerusalém, tomou o rei e os seus chefes e os levou consigo para a Babilônia;",n:"Em 597 antes de Cristo, com o rei Joaquin (2 Reis 24,10–16)."},
{v:13,t:"tomou também um da descendência real, fez com ele uma aliança e o obrigou a um juramento; e levou os poderosos da terra,",n:"Sedecias (2 Reis 24,17)."},
{v:14,t:"para que o reino ficasse humilhado e não se levantasse, mas guardasse a aliança e a cumprisse."},
{v:15,t:"Mas este se revoltou contra ele e enviou mensageiros ao Egito, para que lhe dessem cavalos e muitas tropas. Prosperará? Escapará quem fez essas coisas? Quem rompeu a aliança escapará?",n:"A outra águia é o faraó do Egito, cujo apoio Sedecias buscou contra a Babilônia."},
{v:16,t:"Pela minha vida, oráculo do Senhor Deus, é no lugar do rei que o fez rei, cujo juramento desprezou e cuja aliança rompeu, é no meio da Babilônia que ele morrerá."},
{v:17,t:"E o faraó, com o seu grande exército e a sua multidão numerosa, não o ajudará na guerra, quando se levantarem rampas e se construírem trincheiras para matar muitas vidas."},
{v:18,t:"Pois desprezou o juramento, rompendo a aliança; eis que tinha dado a mão, e, depois de fazer tudo isso, não escapará."},
{v:19,t:"Por isso assim diz o Senhor Deus: Pela minha vida, o meu juramento, que ele desprezou, e a minha aliança, que ele rompeu, eu os farei cair sobre a sua cabeça.",np:1},
{v:20,t:"Estenderei sobre ele a minha rede, e ele será apanhado no meu laço; eu o levarei para a Babilônia e ali o julgarei pela infidelidade que cometeu contra mim."},
{v:21,t:"Todos os melhores das suas tropas cairão pela espada, e os que restarem serão espalhados a todos os ventos; e sabereis que eu, o Senhor, falei."},
{s:"O rebento plantado no monte alto"},
{v:22,l:["Assim diz o Senhor Deus:","Eu mesmo tomarei da copa do alto cedro e o plantarei;","do mais alto dos seus ramos arrancarei um broto tenro","e o plantarei sobre um monte alto e elevado."],n:"Promessa messiânica: um novo rei da linhagem de Davi (compare Isaías 11,1; Jeremias 23,5). A parábola do grão de mostarda, em cujos ramos as aves fazem ninho, ecoa estes versículos (Mateus 13,31–32)."},
{v:23,l:["Eu o plantarei no alto monte de Israel;","ele produzirá ramos e dará fruto","e se tornará um cedro magnífico;","debaixo dele habitarão todas as aves,","e todo tipo de pássaro fará ninho à sombra dos seus ramos."],np:1},
{v:24,l:["E todas as árvores do campo saberão","que eu, o Senhor,","abaixo a árvore alta","e elevo a árvore baixa,","faço secar a árvore verde","e faço brotar a árvore seca.","Eu, o Senhor, falei e o farei."],np:1}
];

window.TEXTOS_SEED["ezequiel"][18] = [
{s:"A responsabilidade pessoal"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,l:["Que quereis dizer, repetindo este provérbio sobre a terra de Israel:","Os pais comeram uvas verdes,","e os dentes dos filhos ficaram embotados?"],np:1,n:"Compare Jeremias 31,29–30."},
{v:3,t:"Pela minha vida, oráculo do Senhor Deus, não repetireis mais este provérbio em Israel.",np:1},
{v:4,t:"Eis que todas as vidas me pertencem: tanto a vida do pai como a vida do filho são minhas; a pessoa que pecar é que morrerá.",np:1},
{v:5,t:"Se um homem é justo e pratica o direito e a justiça,"},
{v:6,t:"se não come nos montes, nem levanta os olhos para os ídolos da casa de Israel, se não desonra a mulher do seu próximo, nem se aproxima da mulher durante a menstruação,",n:"Comer nos montes: participar de banquetes sagrados nos santuários pagãos."},
{v:7,t:"se não oprime ninguém, devolve o penhor ao devedor, não rouba, dá o seu pão ao faminto e cobre com roupa o que está nu,"},
{v:8,t:"se não empresta com usura, nem cobra juros, se afasta a mão da iniquidade e julga com verdade entre um homem e outro,"},
{v:9,t:"se anda nos meus preceitos e guarda os meus decretos, agindo com fidelidade, esse é justo e certamente viverá, oráculo do Senhor Deus."},
{v:10,t:"Mas, se ele gerar um filho violento, que derrama sangue e faz alguma dessas coisas,",np:1},
{v:11,t:"embora o pai não tenha feito nada disso; um filho que come nos montes, desonra a mulher do seu próximo,"},
{v:12,t:"oprime o pobre e o necessitado, pratica roubos, não devolve o penhor, levanta os olhos para os ídolos, comete abominações,"},
{v:13,t:"empresta com usura e cobra juros, viverá ele? Não viverá. Porque cometeu todas essas abominações, certamente morrerá; o seu sangue cairá sobre ele."},
{v:14,t:"Mas, se este gerar um filho que vê todos os pecados que o pai cometeu, e tem temor, e não faz nada semelhante:",np:1},
{v:15,t:"não come nos montes, não levanta os olhos para os ídolos da casa de Israel, não desonra a mulher do seu próximo,"},
{v:16,t:"não oprime ninguém, não retém o penhor, não rouba, dá o seu pão ao faminto e cobre com roupa o que está nu,"},
{v:17,t:"afasta a mão da injustiça, não cobra usura nem juros, cumpre os meus decretos e anda nos meus preceitos, esse não morrerá pela iniquidade do pai, mas certamente viverá."},
{v:18,t:"O pai, porque praticou a extorsão, roubou e fez o que não é bom no meio do seu povo, eis que morreu pela sua iniquidade."},
{v:19,t:"E vós dizeis: Por que o filho não carrega a iniquidade do pai? É que o filho praticou o direito e a justiça, guardou todos os meus preceitos e os cumpriu; por isso certamente viverá."},
{v:20,t:"A pessoa que pecar é que morrerá; o filho não carregará a iniquidade do pai, nem o pai carregará a iniquidade do filho. A justiça do justo estará sobre ele, e a impiedade do ímpio estará sobre ele."},
{s:"A conversão do ímpio e a queda do justo"},
{v:21,t:"Mas, se o ímpio se converter de todos os pecados que cometeu, guardar todos os meus preceitos e praticar o direito e a justiça, certamente viverá; não morrerá."},
{v:22,t:"Nenhuma das transgressões que cometeu será lembrada contra ele; viverá por causa da justiça que praticou."},
{v:23,t:"Acaso tenho eu prazer na morte do ímpio, oráculo do Senhor Deus, e não antes em que se converta dos seus caminhos e viva?"},
{v:24,t:"Mas, se o justo se afastar da sua justiça e praticar a iniquidade, segundo todas as abominações que o ímpio costuma praticar, viverá ele? Nenhuma das obras justas que praticou será lembrada; por causa da infidelidade que cometeu e do pecado em que caiu, por isso morrerá.",np:1},
{v:25,t:"E vós dizeis: O caminho do Senhor não é justo. Ouvi, pois, casa de Israel: É o meu caminho que não é justo? Não são antes os vossos caminhos que são tortos?"},
{v:26,t:"Quando o justo se afasta da sua justiça e pratica a iniquidade, morrerá; morrerá pela iniquidade que praticou."},
{v:27,t:"E quando o ímpio se afasta da impiedade que praticou e pratica o direito e a justiça, ele conserva a sua vida;"},
{v:28,t:"porque refletiu e se afastou de todas as transgressões que cometeu, certamente viverá; não morrerá."},
{v:29,t:"E a casa de Israel diz: O caminho do Senhor não é justo. São os meus caminhos que não são justos, casa de Israel? Não são antes os vossos caminhos que são tortos?"},
{s:"Convertei-vos e vivei"},
{v:30,t:"Por isso eu vos julgarei, casa de Israel, a cada um segundo os seus caminhos, oráculo do Senhor Deus. Convertei-vos e afastai-vos de todas as vossas transgressões, e a iniquidade não será para vós ocasião de queda."},
{v:31,t:"Lançai para longe de vós todas as transgressões que cometestes e fazei para vós um coração novo e um espírito novo. Por que haveríeis de morrer, casa de Israel?"},
{v:32,t:"Pois eu não tenho prazer na morte de quem morre, oráculo do Senhor Deus. Convertei-vos e vivei!"}
];

window.TEXTOS_SEED["ezequiel"][19] = [
{s:"Lamentação sobre os príncipes de Israel"},
{v:1,t:"E tu, entoa uma lamentação sobre os príncipes de Israel"},
{v:2,l:["e dize:","Que leoa era a tua mãe","entre os leões!","Deitava-se no meio dos leõezinhos","e criava os seus filhotes."],n:"A leoa é a mãe dos reis, ou o próprio reino de Judá. O primeiro filhote é Joacaz, levado ao Egito em 609 antes de Cristo (2 Reis 23,31–34); o segundo é provavelmente Joaquin, levado à Babilônia em 597 (2 Reis 24,8–15)."},
{v:3,l:["Criou um dos seus filhotes,","que se tornou um leão;","aprendeu a apanhar a presa","e devorou homens."],np:1},
{v:4,l:["As nações se reuniram contra ele,","e ele foi apanhado na cova delas;","e o levaram com argolas","para a terra do Egito."],np:1},
{v:5,l:["Quando ela viu que tinha esperado em vão","e que a sua esperança estava perdida,","tomou outro dos seus filhotes","e fez dele um leão."],np:1},
{v:6,l:["Ele andava no meio dos leões,","tornou-se um leão,","aprendeu a apanhar a presa","e devorou homens;"],np:1},
{v:7,l:["destruiu as suas fortalezas","e devastou as suas cidades.","A terra e tudo o que ela contém ficaram aterrados","com o ruído do seu rugido."],np:1},
{v:8,l:["As nações das províncias vizinhas","se reuniram contra ele","e estenderam sobre ele a sua rede;","ele foi apanhado na cova delas."],np:1},
{v:9,l:["Puseram-no numa jaula, com argolas,","e o levaram ao rei da Babilônia,","que o meteu numa prisão,","para que a sua voz não se ouvisse mais","sobre os montes de Israel."],np:1},
{s:"A videira arrancada"},
{v:10,l:["A tua mãe era como uma videira","plantada junto da água;","era fecunda e frondosa","por causa das águas abundantes;"]},
{v:11,l:["tinha ramos fortes,","que serviam de cetro aos soberanos;","a sua estatura se elevou","até as nuvens,","e era vista na sua altura,","com a multidão dos seus ramos."],np:1},
{v:12,l:["Mas foi arrancada com furor","e lançada por terra;","o vento abrasador secou o seu fruto;","o seu ramo forte foi quebrado e secou,","e o fogo o devorou."],np:1},
{v:13,l:["E agora está plantada no deserto,","numa terra árida e sedenta."],np:1},
{v:14,l:["Saiu fogo do seu ramo","e devorou o seu fruto;","e nela não ficou nenhum ramo forte,","nenhum cetro para reinar.","Esta é uma lamentação, e servirá de lamentação."],np:1}
];

window.TEXTOS_SEED["ezequiel"][20] = [
{s:"A história da infidelidade de Israel"},
{v:1,t:"No sétimo ano, no quinto mês, no dia dez do mês, alguns dos anciãos de Israel vieram consultar o Senhor e se sentaram diante de mim.",n:"Em agosto de 591 antes de Cristo."},
{v:2,t:"A palavra do Senhor me foi dirigida:"},
{v:3,t:"Filho do homem, fala aos anciãos de Israel e dize-lhes: Assim diz o Senhor Deus: Viestes para me consultar? Pela minha vida, não vos responderei, oráculo do Senhor Deus."},
{v:4,t:"Queres julgá-los? Queres julgá-los, filho do homem? Mostra-lhes as abominações dos seus pais."},
{v:5,t:"Dize-lhes: Assim diz o Senhor Deus: No dia em que escolhi Israel, levantei a mão em juramento à descendência da casa de Jacó e me dei a conhecer a eles na terra do Egito; levantei a mão em juramento em favor deles, dizendo: Eu sou o Senhor, vosso Deus.",np:1,n:"Levantar a mão: gesto de juramento."},
{v:6,t:"Naquele dia levantei a mão em juramento em favor deles, prometendo tirá-los da terra do Egito e levá-los à terra que eu tinha escolhido para eles, onde corre leite e mel, a mais bela de todas as terras."},
{v:7,t:"E lhes disse: Cada um de vós jogue fora as coisas detestáveis que atraem os seus olhos, e não vos contamineis com os ídolos do Egito: eu sou o Senhor, vosso Deus."},
{v:8,t:"Mas eles se rebelaram contra mim e não quiseram escutar-me; nenhum deles jogou fora as coisas detestáveis que atraíam os seus olhos, nem abandonou os ídolos do Egito. Então pensei em derramar sobre eles o meu furor e esgotar neles a minha ira, no meio da terra do Egito."},
{v:9,t:"Mas agi por causa do meu nome, para que ele não fosse profanado aos olhos das nações no meio das quais eles estavam e diante das quais eu me tinha dado a conhecer a eles, para tirá-los da terra do Egito."},
{v:10,t:"Tirei-os, pois, da terra do Egito e os levei para o deserto.",np:1},
{v:11,t:"Dei-lhes os meus preceitos e lhes fiz conhecer os meus decretos, que o homem deve cumprir para viver por eles."},
{v:12,t:"Dei-lhes também os meus sábados, para que fossem um sinal entre mim e eles, para que soubessem que eu sou o Senhor, que os santifica.",np:1},
{v:13,t:"Mas a casa de Israel se rebelou contra mim no deserto: não andaram nos meus preceitos e rejeitaram os meus decretos, que o homem deve cumprir para viver por eles, e profanaram gravemente os meus sábados. Então pensei em derramar sobre eles o meu furor no deserto, para exterminá-los."},
{v:14,t:"Mas agi por causa do meu nome, para que ele não fosse profanado aos olhos das nações diante das quais eu os tinha tirado do Egito."},
{v:15,t:"Contudo, levantei a mão contra eles no deserto, jurando que não os levaria à terra que lhes tinha dado, onde corre leite e mel, a mais bela de todas as terras,"},
{v:16,t:"porque rejeitaram os meus decretos, não andaram nos meus preceitos e profanaram os meus sábados, pois o seu coração ia atrás dos seus ídolos."},
{v:17,t:"Mas o meu olho teve piedade deles, e não os destruí; não os exterminei no deserto."},
{v:18,t:"Disse, então, aos seus filhos no deserto: Não andeis nos preceitos dos vossos pais, não guardeis os seus costumes e não vos contamineis com os seus ídolos.",np:1},
{v:19,t:"Eu sou o Senhor, vosso Deus: andai nos meus preceitos, guardai os meus decretos e cumpri-os,",np:1},
{v:20,t:"santificai os meus sábados, para que sejam um sinal entre mim e vós, para que se saiba que eu sou o Senhor, vosso Deus."},
{v:21,t:"Mas os filhos se rebelaram contra mim: não andaram nos meus preceitos e não guardaram nem cumpriram os meus decretos, que o homem deve cumprir para viver por eles, e profanaram os meus sábados. Então ameacei derramar sobre eles o meu furor e esgotar neles a minha ira no deserto."},
{v:22,t:"Mas retirei a mão e agi por causa do meu nome, para que ele não fosse profanado aos olhos das nações diante das quais eu os tinha tirado do Egito."},
{v:23,t:"Contudo, levantei a mão contra eles no deserto, jurando que os dispersaria entre as nações e os espalharia pelos países,"},
{v:24,t:"porque não tinham cumprido os meus decretos, tinham rejeitado os meus preceitos e profanado os meus sábados, e os seus olhos iam atrás dos ídolos dos seus pais."},
{v:25,t:"Por isso também eu lhes dei preceitos que não eram bons e decretos pelos quais não podiam viver;",n:"Nota do tradutor: afirmação dura, à maneira do Antigo Testamento, que atribui a Deus até o endurecimento do povo (compare Isaías 6,9–10; Romanos 1,24–28); o texto não foi suavizado."},
{v:26,t:"e os contaminei com as suas próprias ofertas, quando ofereciam todo primogênito, para os encher de horror, a fim de que soubessem que eu sou o Senhor."},
{s:"A infidelidade na terra prometida"},
{v:27,t:"Por isso fala à casa de Israel, filho do homem, e dize-lhes: Assim diz o Senhor Deus: Também nisto os vossos pais me ultrajaram, sendo-me infiéis:"},
{v:28,t:"depois que os levei à terra que tinha jurado dar-lhes, viram toda colina elevada e toda árvore frondosa e ali ofereceram os seus sacrifícios, apresentaram as suas ofertas que me provocavam, ali puseram o seu perfume agradável e ali derramaram as suas libações."},
{v:29,t:"Eu lhes disse: Que lugar alto é esse aonde ides? E até hoje ele se chama Lugar Alto.",n:"No hebraico, jogo de palavras entre bamá (lugar alto) e ba (ir)."},
{v:30,t:"Por isso dize à casa de Israel: Assim diz o Senhor Deus: Vós vos contaminais seguindo o caminho dos vossos pais e vos prostituís atrás das suas coisas detestáveis;",np:1},
{v:31,t:"e, quando ofereceis os vossos dons e fazeis passar pelo fogo os vossos filhos, vós vos contaminais com todos os vossos ídolos até hoje; e eu vos responderei, casa de Israel? Pela minha vida, oráculo do Senhor Deus, não vos responderei."},
{v:32,t:"Não se realizará o que pensais, quando dizeis: Seremos como as nações, como os povos da terra, servindo a madeira e a pedra."},
{s:"O novo êxodo"},
{v:33,t:"Pela minha vida, oráculo do Senhor Deus, é com mão forte, com braço estendido e com furor derramado que reinarei sobre vós."},
{v:34,t:"Eu vos tirarei dentre os povos e vos reunirei dos países por onde fostes dispersos, com mão forte, com braço estendido e com furor derramado."},
{v:35,t:"Eu vos levarei ao deserto dos povos, e ali entrarei em julgamento convosco, face a face."},
{v:36,t:"Como entrei em julgamento com os vossos pais no deserto da terra do Egito, assim entrarei em julgamento convosco, oráculo do Senhor Deus;"},
{v:37,t:"eu vos farei passar debaixo do meu cajado e vos farei entrar nos laços da aliança.",n:"Imagem do pastor que conta as ovelhas fazendo-as passar debaixo do cajado (compare Levítico 27,32)."},
{v:38,t:"Separarei de vós os rebeldes e os que se revoltam contra mim; eu os tirarei da terra onde vivem como estrangeiros, mas não entrarão na terra de Israel; e sabereis que eu sou o Senhor."},
{v:39,t:"Quanto a vós, casa de Israel, assim diz o Senhor Deus: Ide, sirva cada um os seus ídolos! Mas depois certamente me escutareis e não profanareis mais o meu santo nome com as vossas ofertas e com os vossos ídolos."},
{v:40,t:"Pois no meu santo monte, no alto monte de Israel, oráculo do Senhor Deus, ali me servirá toda a casa de Israel, todos eles, na terra; ali terei prazer neles, ali pedirei as vossas ofertas e as primícias dos vossos dons, com todas as vossas coisas santas."},
{v:41,t:"Eu vos acolherei como perfume agradável, quando vos tirar dentre os povos e vos reunir dos países por onde fostes dispersos, e manifestarei em vós a minha santidade aos olhos das nações."},
{v:42,t:"E sabereis que eu sou o Senhor, quando vos levar à terra de Israel, à terra que jurei, levantando a mão, dar aos vossos pais."},
{v:43,t:"Ali vos lembrareis dos vossos caminhos e de todas as ações com que vos contaminastes, e tereis nojo de vós mesmos por todas as maldades que cometestes."},
{v:44,t:"E sabereis que eu sou o Senhor, quando agir convosco por causa do meu nome, não segundo os vossos maus caminhos nem segundo as vossas ações corruptas, casa de Israel, oráculo do Senhor Deus.",n:"Em algumas Bíblias, o capítulo 20 continua com mais cinco versículos (20,45–49), que aqui, como no hebraico, são 21,1–5."}
];

window.TEXTOS_SEED["ezequiel"][21] = [
{s:"O fogo na floresta do Negueb"},
{v:1,t:"A palavra do Senhor me foi dirigida:",n:"Em algumas Bíblias, 21,1–5 é numerado 20,45–49, e o resto do capítulo tem a numeração diminuída de cinco (21,6–37 = 21,1–32)."},
{v:2,t:"Filho do homem, volta o rosto para o sul, deixa cair a tua palavra sobre o meio-dia e profetiza contra a floresta do campo do Negueb."},
{v:3,t:"Dize à floresta do Negueb: Ouve a palavra do Senhor. Assim diz o Senhor Deus: Eis que vou atear em ti um fogo que devorará em ti toda árvore verde e toda árvore seca; a chama ardente não se apagará, e todo rosto será queimado por ela, do sul ao norte."},
{v:4,t:"E toda carne verá que eu, o Senhor, a acendi; ela não se apagará."},
{v:5,t:"Eu disse: Ah, Senhor Deus! Eles dizem de mim: Este aí não fala só por parábolas?"},
{s:"A espada do Senhor"},
{v:6,t:"A palavra do Senhor me foi dirigida:"},
{v:7,t:"Filho do homem, volta o rosto para Jerusalém, deixa cair a tua palavra sobre os santuários e profetiza contra a terra de Israel."},
{v:8,t:"Dize à terra de Israel: Assim diz o Senhor Deus: Eis que estou contra ti: tirarei a minha espada da bainha e exterminarei do meio de ti o justo e o ímpio.",n:"Nota do tradutor: o castigo coletivo atinge justos e ímpios, em aparente contraste com 9,4–6 e 18,1–32; o texto não foi suavizado."},
{v:9,t:"E, porque vou exterminar do meio de ti o justo e o ímpio, a minha espada sairá da bainha contra toda carne, do sul ao norte,"},
{v:10,t:"para que toda carne saiba que eu, o Senhor, tirei a minha espada da bainha, e ela não voltará mais."},
{v:11,t:"E tu, filho do homem, geme com os rins quebrados; geme amargamente diante deles.",np:1},
{v:12,t:"E, se te perguntarem por que gemes, dirás: Por causa da notícia que chega; todo coração desfalecerá, todas as mãos perderão a força, todo espírito se abaterá, e todos os joelhos se desfarão em água. Eis que chega e se cumprirá, oráculo do Senhor Deus."},
{s:"O cântico da espada"},
{v:13,t:"A palavra do Senhor me foi dirigida:"},
{v:14,l:["Filho do homem, profetiza e dize: Assim diz o Senhor Deus: Dize:","Uma espada, uma espada foi afiada","e também polida;"],n:"O texto hebraico destes versículos é muito difícil; a Nova Vulgata o interpreta como aqui se traduz."},
{v:15,l:["foi afiada para matar vítimas,","foi polida para brilhar."],np:1},
{v:16,l:["Foi entregue para ser polida,","para ser empunhada;","esta espada foi afiada, esta foi polida,","para ser posta na mão do matador."],np:1},
{v:17,l:["Grita e geme, filho do homem,","porque ela está voltada contra o meu povo,","contra todos os chefes de Israel,","entregues à espada com o meu povo."],np:1},
{v:18,l:["Por isso bate na coxa,","pois é uma prova,","oráculo do Senhor Deus."],np:1},
{v:19,l:["Tu, pois, filho do homem,","profetiza e bate palmas.","Que a espada se redobre,","que a espada dos mortos se triplique: é a espada do grande massacre,","que os cerca,"],np:1},
{v:20,l:["para que o coração desfaleça","e se multipliquem os que caem.","Em todas as suas portas","pus o massacre da espada:","ai! Foram afiadas e polidas para brilhar,","amoladas para a matança!"],np:1},
{v:21,l:["Afia-te, vai para a direita ou para a esquerda,","para onde estiver voltado o teu gume!"],np:1},
{v:22,l:["Também eu baterei palmas","e saciarei o meu furor;","eu, o Senhor, falei."],np:1},
{s:"O rei da Babilônia na encruzilhada"},
{v:23,t:"A palavra do Senhor me foi dirigida:"},
{v:24,t:"E tu, filho do homem, traça dois caminhos por onde venha a espada do rei da Babilônia; ambos sairão de uma mesma terra; e põe uma placa, põe-na no começo do caminho de cada cidade."},
{v:25,t:"Traçarás o caminho por onde a espada virá contra Rabá dos amonitas e contra Judá, contra Jerusalém, a fortificada."},
{v:26,t:"Pois o rei da Babilônia está parado na encruzilhada, no começo dos dois caminhos, para consultar a sorte: sacode as flechas, interroga os terafins, examina o fígado.",n:"Três formas de adivinhação: tirar flechas marcadas de uma aljava, consultar ídolos domésticos e examinar o fígado das vítimas."},
{v:27,t:"Na sua mão direita saiu a sorte para Jerusalém: pôr aríetes, abrir a boca para o massacre, levantar a voz em gritos de guerra, pôr aríetes contra as portas, levantar rampas e construir trincheiras.",np:1},
{v:28,t:"Mas, aos olhos deles, isso parecerá um oráculo vão, pois têm os juramentos mais sagrados; ele, porém, lembrará a culpa deles, para que sejam capturados.",n:"Os de Jerusalém confiam nos juramentos; mas foi justamente a quebra do juramento feito a Nabucodonosor que atraiu o castigo (17,13–19)."},
{v:29,t:"Por isso assim diz o Senhor Deus: Porque fizestes lembrar a vossa culpa, descobrindo as vossas transgressões e mostrando os vossos pecados em todas as vossas ações; porque fostes lembrados, sereis capturados pela mão."},
{v:30,t:"E tu, profano e ímpio príncipe de Israel, cujo dia chegou no tempo do castigo final —",n:"O príncipe: o rei Sedecias."},
{v:31,t:"assim diz o Senhor Deus — tira o turbante, depõe a coroa; nada será como antes. Seja exaltado o humilde, e humilhado o que é elevado."},
{v:32,t:"Ruína, ruína, ruína farei dela; mas isso não acontecerá até que venha aquele a quem pertence o julgamento, e a ele o entregarei.",n:"Alusão a Gênesis 49,10; a tradição viu aqui um anúncio do Messias."},
{s:"Contra os amonitas"},
{v:33,t:"E tu, filho do homem, profetiza e dize: Assim diz o Senhor Deus a respeito dos amonitas e dos seus insultos; dize: A espada, a espada está desembainhada para matar, polida para devorar, para brilhar como o relâmpago,"},
{v:34,t:"enquanto as tuas visões são vãs e os teus oráculos, mentirosos, para ser posta sobre o pescoço dos ímpios profanos, cujo dia chegou no tempo do castigo final."},
{v:35,t:"Volte ela para a bainha! No lugar onde foste criado, na terra da tua origem, eu te julgarei.",n:"O julgamento se volta agora contra os próprios amonitas."},
{v:36,t:"Derramarei sobre ti o meu furor, soprarei contra ti o fogo da minha ira e te entregarei nas mãos de homens brutais, artífices de destruição."},
{v:37,t:"Serás pasto para o fogo, o teu sangue ficará no meio da terra; não haverá mais lembrança de ti, pois eu, o Senhor, falei."}
];

window.TEXTOS_SEED["ezequiel"][22] = [
{s:"Os crimes da cidade sanguinária"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,t:"E tu, filho do homem, vais julgar, vais julgar a cidade sanguinária?"},
{v:3,t:"Mostra-lhe todas as suas abominações e dize: Assim diz o Senhor Deus: Cidade que derrama sangue no meio de si, apressando a sua hora, e que fez ídolos contra si mesma, para se contaminar!"},
{v:4,t:"Pelo sangue que derramaste te tornaste culpada, e pelos ídolos que fizeste te contaminaste; apressaste os teus dias e chegaste ao termo dos teus anos. Por isso fiz de ti objeto de insulto para as nações e de zombaria para todos os países."},
{v:5,t:"Os que estão perto e os que estão longe zombarão de ti, cidade de nome manchado e cheia de tumulto."},
{v:6,t:"Eis que os príncipes de Israel, cada um segundo a sua força, estão em ti para derramar sangue."},
{v:7,t:"Em ti se despreza pai e mãe, no meio de ti se oprime o estrangeiro, em ti se maltrata o órfão e a viúva."},
{v:8,t:"Desprezaste as minhas coisas santas e profanaste os meus sábados."},
{v:9,t:"Há em ti caluniadores, para derramar sangue; em ti se come nos montes; no meio de ti se praticam infâmias."},
{v:10,t:"Em ti se descobre a nudez do pai; em ti se violenta a mulher na impureza da menstruação;"},
{v:11,t:"um comete abominação com a mulher do seu próximo, outro contamina criminosamente a sua nora, outro ainda violenta em ti a sua irmã, filha do seu pai.",n:"Compare Levítico 18 e 20."},
{v:12,t:"Em ti se aceitam subornos para derramar sangue; cobraste usura e juros, exploraste com avareza o teu próximo e te esqueceste de mim, oráculo do Senhor Deus."},
{v:13,t:"Eis que bato as mãos diante do lucro desonesto que acumulaste e do sangue que foi derramado no meio de ti.",np:1},
{v:14,t:"Resistirá o teu coração, ou terão força as tuas mãos nos dias em que eu agir contra ti? Eu, o Senhor, falei e o farei;"},
{v:15,t:"eu te dispersarei entre as nações, te espalharei pelos países e farei desaparecer de ti a tua impureza;"},
{v:16,t:"e por tua causa serei profanado aos olhos das nações, e saberás que eu sou o Senhor."},
{s:"O crisol"},
{v:17,t:"A palavra do Senhor me foi dirigida:"},
{v:18,t:"Filho do homem, a casa de Israel se tornou para mim escória; todos eles são como prata, bronze, estanho, ferro e chumbo no meio do forno: tornaram-se escória."},
{v:19,t:"Por isso assim diz o Senhor Deus: Porque todos vós vos tornastes escória, eis que vou reunir-vos no meio de Jerusalém,"},
{v:20,t:"como se junta prata, bronze, ferro, chumbo e estanho no meio do forno, para acender o fogo e fundir tudo: assim eu vos reunirei na minha ira e no meu furor, vos colocarei ali e vos fundirei;"},
{v:21,t:"sim, vos reunirei e soprarei contra vós o fogo do meu furor, e sereis fundidos no meio dela."},
{v:22,t:"Como se funde a prata no meio do forno, assim sereis fundidos no meio dela; e sabereis que eu, o Senhor, derramei sobre vós o meu furor."},
{s:"Todas as classes corrompidas"},
{v:23,t:"A palavra do Senhor me foi dirigida:"},
{v:24,t:"Filho do homem, dize-lhe: Tu és uma terra sobre a qual não caiu chuva nem aguaceiro no dia da ira,"},
{v:25,t:"cujos chefes, no meio dela, são como um leão que ruge e despedaça a presa: devoram vidas, tomam riquezas e objetos preciosos, multiplicam as viúvas no meio dela.",n:"Os chefes: assim a Nova Vulgata, com a tradução grega; o hebraico diz: a conspiração dos seus profetas."},
{v:26,t:"Os seus sacerdotes violam a minha lei e profanam as minhas coisas santas; não fazem distinção entre o sagrado e o profano, não ensinam a diferença entre o impuro e o puro, fecham os olhos aos meus sábados, e eu sou profanado no meio deles."},
{v:27,t:"Os seus príncipes, no meio dela, são como lobos que despedaçam a presa, derramando sangue e destruindo vidas para obter lucro desonesto."},
{v:28,t:"Os seus profetas rebocam tudo com cal para eles, com visões vazias e adivinhações mentirosas, dizendo: Assim diz o Senhor Deus, quando o Senhor não falou.",np:1},
{v:29,t:"O povo da terra pratica a extorsão e comete roubos; oprime o pobre e o necessitado e maltrata o estrangeiro sem direito.",np:1},
{v:30,t:"Procurei entre eles um homem que levantasse um muro e se pusesse na brecha diante de mim, em favor da terra, para que eu não a destruísse, e não o encontrei."},
{v:31,t:"Por isso derramei sobre eles o meu furor, eu os consumi no fogo da minha ira e fiz cair sobre a cabeça deles o seu procedimento, oráculo do Senhor Deus."}
];

window.TEXTOS_SEED["ezequiel"][23] = [
{s:"Oola e Ooliba"},
{v:1,t:"A palavra do Senhor me foi dirigida:",n:"Nota do tradutor: como no capítulo 16, a alegoria usa linguagem sexual crua; o texto não foi suavizado. Oola significa a sua tenda; Ooliba, a minha tenda está nela."},
{v:2,t:"Filho do homem, havia duas mulheres, filhas da mesma mãe,"},
{v:3,t:"que se prostituíram no Egito; na sua juventude se prostituíram; ali os seus seios foram apalpados, ali acariciaram os seus peitos virginais."},
{v:4,t:"Chamavam-se Oola, a mais velha, e Ooliba, sua irmã. Elas foram minhas e me deram filhos e filhas. Quanto aos seus nomes: Oola é Samaria, e Ooliba é Jerusalém."},
{v:5,t:"Oola se prostituiu, afastando-se de mim, e se apaixonou pelos seus amantes, os assírios, guerreiros"},
{v:6,t:"vestidos de azul, governadores e magistrados, todos jovens atraentes, cavaleiros montados a cavalo."},
{v:7,t:"Ela se entregou à prostituição com eles, com toda a elite dos filhos da Assíria; e com todos aqueles por quem se apaixonava se contaminava, com todos os seus ídolos."},
{v:8,t:"E não abandonou as prostituições que tinha começado no Egito, pois eles se tinham deitado com ela na sua juventude, tinham apalpado os seus seios virginais e derramado sobre ela a sua luxúria."},
{v:9,t:"Por isso eu a entreguei nas mãos dos seus amantes, nas mãos dos filhos da Assíria, pelos quais se apaixonara;"},
{v:10,t:"eles descobriram a sua nudez, tomaram os seus filhos e as suas filhas e a mataram à espada; e ela se tornou famosa entre as mulheres, depois que executaram nela o julgamento.",n:"A queda de Samaria, em 722 antes de Cristo (2 Reis 17)."},
{v:11,t:"A sua irmã Ooliba viu isso, mas foi ainda mais desenfreada na sua paixão e nas suas prostituições do que a irmã.",np:1},
{v:12,t:"Apaixonou-se pelos filhos da Assíria: governadores e magistrados, guerreiros vestidos com roupas magníficas, cavaleiros montados a cavalo, todos jovens atraentes."},
{v:13,t:"E vi que ela se contaminara: ambas seguiam o mesmo caminho."},
{v:14,t:"Mas ela aumentou ainda as suas prostituições. Viu homens desenhados na parede, figuras de caldeus pintadas de vermelho,"},
{v:15,t:"com cinturões na cintura e turbantes pendentes na cabeça, todos com aparência de oficiais de carros, à semelhança dos babilônios, cuja pátria é a Caldeia."},
{v:16,t:"Ela se apaixonou por eles à primeira vista e lhes mandou mensageiros na Caldeia.",np:1},
{v:17,t:"Os babilônios vieram a ela, ao leito dos amores, e a contaminaram com as suas luxúrias; e, depois de ser contaminada por eles, ela se afastou deles com desgosto."},
{v:18,t:"Como ela exibiu as suas prostituições e descobriu a sua nudez, eu me afastei dela com desgosto, como me tinha afastado da sua irmã."},
{v:19,t:"Mas ela multiplicou as suas prostituições, lembrando-se dos dias da sua juventude, quando se prostituía na terra do Egito;"},
{v:20,t:"apaixonou-se pelos seus amantes, que tinham membros como os dos jumentos e ejaculação como a dos cavalos."},
{v:21,t:"Assim desejaste de novo a infâmia da tua juventude, quando no Egito apalpavam os teus seios e acariciavam os teus peitos juvenis."},
{s:"O castigo de Ooliba"},
{v:22,t:"Por isso, Ooliba, assim diz o Senhor Deus: Eis que vou suscitar contra ti os teus amantes, de quem te afastaste com desgosto, e os reunirei contra ti de todos os lados:"},
{v:23,t:"os babilônios e todos os caldeus, os de Facud, de Soa e de Coa, e com eles todos os filhos da Assíria, jovens atraentes, governadores e magistrados, todos eles oficiais de carros e homens ilustres, todos montados a cavalo."},
{v:24,t:"Virão contra ti com carros e rodas e uma multidão de povos; de todos os lados se armarão contra ti de escudo, broquel e capacete; e eu lhes entregarei o julgamento, e eles te julgarão segundo as suas leis."},
{v:25,t:"Descarregarei sobre ti o meu ciúme, e eles te tratarão com furor: cortarão o teu nariz e as tuas orelhas, e o que restar de ti cairá pela espada; tomarão os teus filhos e as tuas filhas, e o que restar de ti será devorado pelo fogo."},
{v:26,t:"Eles te despojarão das tuas roupas e levarão as tuas joias magníficas;"},
{v:27,t:"porei fim à tua infâmia e à prostituição que trouxeste da terra do Egito; não levantarás mais os olhos para eles e não te lembrarás mais do Egito."},
{v:28,t:"Pois assim diz o Senhor Deus: Eis que vou entregar-te nas mãos daqueles que odeias, nas mãos daqueles de quem te afastaste com desgosto;"},
{v:29,t:"eles te tratarão com ódio, tomarão todo o fruto do teu trabalho e te deixarão nua e coberta de vergonha; e se descobrirá a vergonha das tuas prostituições, a tua infâmia e as tuas prostituições."},
{v:30,t:"Isto te farão, porque te prostituíste com as nações e te contaminaste com os seus ídolos.",np:1},
{v:31,t:"Seguiste o caminho da tua irmã; por isso porei na tua mão a taça dela."},
{v:32,l:["Assim diz o Senhor Deus:","Beberás a taça da tua irmã,","funda e larga;","serás objeto de zombaria e de escárnio:","ela tem grande capacidade."],np:1},
{v:33,l:["Ficarás cheia de embriaguez e de dor,","taça de espanto e de desolação,","taça da tua irmã Samaria;"],np:1},
{v:34,l:["tu a beberás e a esgotarás até a borra;","roerás os seus cacos","e rasgarás os teus seios,","pois eu falei,","oráculo do Senhor Deus."],np:1},
{v:35,t:"Por isso assim diz o Senhor Deus: Porque te esqueceste de mim e me lançaste para trás das costas, carrega também tu a tua infâmia e as tuas prostituições.",np:1},
{s:"O julgamento das duas irmãs"},
{v:36,t:"O Senhor me disse: Filho do homem, queres julgar Oola e Ooliba? Anuncia-lhes as suas abominações."},
{v:37,t:"Pois cometeram adultério, e há sangue nas suas mãos; cometeram adultério com os seus ídolos e até lhes ofereceram, para serem devorados, os filhos que me tinham dado à luz."},
{v:38,t:"E ainda me fizeram isto: naquele mesmo dia contaminaram o meu santuário e profanaram os meus sábados."},
{v:39,t:"Depois de imolar os seus filhos aos seus ídolos, entravam no meu santuário naquele mesmo dia para profaná-lo; eis o que fizeram no meio da minha casa."},
{v:40,t:"Mandaram até buscar homens que vinham de longe, aos quais tinham enviado mensageiros; e eis que eles vieram. Para eles te banhaste, pintaste os olhos e te enfeitaste com adornos;"},
{v:41,t:"sentaste-te num leito magnífico, diante do qual havia uma mesa preparada, e sobre ela puseste o meu incenso e o meu óleo."},
{v:42,t:"Ouvia-se ali o ruído de uma multidão alegre; e, além desses homens, traziam do deserto uma multidão de gente; eles puseram braceletes nas mãos delas e coroas magníficas nas suas cabeças."},
{v:43,t:"Eu disse daquela que estava gasta pelos adultérios: Agora também esta continuará a prostituir-se."},
{v:44,t:"E entraram nela como se entra numa prostituta; assim entravam em Oola e em Ooliba, mulheres infames."},
{v:45,t:"Mas homens justos as julgarão, com o julgamento das adúlteras e das assassinas, porque são adúlteras, e há sangue nas suas mãos."},
{v:46,t:"Pois assim diz o Senhor Deus: Convoca contra elas uma assembleia e entrega-as ao terror e ao saque;",np:1},
{v:47,t:"a assembleia as apedrejará e as traspassará com as suas espadas; matarão os seus filhos e as suas filhas e queimarão as suas casas."},
{v:48,t:"Assim farei cessar a infâmia na terra, e todas as mulheres aprenderão a não imitar a vossa infâmia."},
{v:49,t:"Farão cair sobre vós a vossa infâmia, e carregareis os pecados da vossa idolatria; e sabereis que eu sou o Senhor Deus."}
];

window.TEXTOS_SEED["ezequiel"][24] = [
{s:"A panela enferrujada"},
{v:1,t:"No nono ano, no décimo mês, no dia dez do mês, a palavra do Senhor me foi dirigida:",n:"Em janeiro de 588 antes de Cristo, o dia em que começou o cerco de Jerusalém (2 Reis 25,1)."},
{v:2,t:"Filho do homem, escreve o nome deste dia, deste mesmo dia: hoje o rei da Babilônia atacou Jerusalém."},
{v:3,l:["Propõe uma parábola a esta casa rebelde e dize-lhes: Assim diz o Senhor Deus:","Põe a panela no fogo, põe-na","e derrama água dentro dela."]},
{v:4,l:["Junta nela os pedaços de carne,","todos os pedaços bons, a coxa e a espádua;","enche-a dos melhores ossos,"],np:1},
{v:5,l:["toma o melhor do rebanho.","Empilha também lenha debaixo dela;","que os pedaços fervam,","e cozinhe os ossos dentro dela."],np:1},
{v:6,l:["Por isso assim diz o Senhor Deus:","Ai da cidade sanguinária,","da panela cheia de ferrugem,","cuja ferrugem não sai dela!","Tira dela pedaço por pedaço,","sem tirar a sorte sobre ela."],np:1},
{v:7,l:["Pois o sangue que ela derramou está no meio dela;","ela o derramou sobre a rocha nua;","não o derramou sobre a terra,","para que o pó pudesse cobri-lo;"],np:1,n:"O sangue devia ser coberto com terra (Levítico 17,13); o sangue descoberto clama por vingança (compare Gênesis 4,10)."},
{v:8,l:["para fazer subir o meu furor","e executar a vingança,","pus o seu sangue","sobre a rocha nua, para que não fosse coberto."],np:1},
{v:9,l:["Por isso assim diz o Senhor Deus:","Ai da cidade sanguinária!","Também eu farei uma grande fogueira."],np:1},
{v:10,l:["Amontoa a lenha, acende o fogo,","cozinha bem a carne,","derrama o caldo,","e que os ossos se queimem."],np:1},
{v:11,l:["Depois põe a panela vazia sobre as brasas,","para que se aqueça e o seu bronze fique em brasa,","para que se funda nela a sua impureza","e desapareça a sua ferrugem."],np:1},
{v:12,l:["Trabalho inútil!","A sua grossa ferrugem não sai,","nem mesmo com o fogo."],np:1},
{v:13,t:"A tua impureza é abominável; porque eu quis purificar-te, e não ficaste pura da tua imundície, não ficarás mais pura enquanto eu não saciar em ti o meu furor.",np:1},
{v:14,t:"Eu, o Senhor, falei; isso vai acontecer, e eu o farei: não recuarei, não terei piedade nem me arrependerei. Eu te julgarei segundo os teus caminhos e segundo as tuas obras, oráculo do Senhor."},
{s:"A morte da esposa do profeta"},
{v:15,t:"A palavra do Senhor me foi dirigida:"},
{v:16,t:"Filho do homem, eis que vou tirar-te de repente a delícia dos teus olhos; mas não farás lamentação, não chorarás e não derramarás lágrimas."},
{v:17,t:"Geme em silêncio, não faças luto pelos mortos; amarra o teu turbante, calça as tuas sandálias, não cubras o rosto e não comas o pão do luto."},
{v:18,t:"Falei ao povo de manhã, e à tarde a minha mulher morreu; e na manhã seguinte fiz como me tinha sido ordenado."},
{v:19,t:"O povo me perguntou: Não nos explicarás o que significam para nós essas coisas que fazes?"},
{v:20,t:"Eu lhes respondi: A palavra do Senhor me foi dirigida:"},
{v:21,t:"Dize à casa de Israel: Assim diz o Senhor Deus: Eis que vou profanar o meu santuário, o orgulho da vossa força, a delícia dos vossos olhos e o anseio da vossa alma; e os vossos filhos e as vossas filhas que deixastes cairão pela espada."},
{v:22,t:"Fareis como eu fiz: não cobrireis o rosto e não comereis o pão do luto;"},
{v:23,t:"tereis os turbantes na cabeça e as sandálias nos pés; não fareis lamentação nem chorareis, mas definhareis nas vossas iniquidades e gemereis uns com os outros."},
{v:24,t:"Ezequiel será para vós um sinal: fareis tudo o que ele fez; quando isso acontecer, sabereis que eu sou o Senhor Deus."},
{v:25,t:"E tu, filho do homem, no dia em que eu lhes tirar a sua força, a alegria do seu esplendor, a delícia dos seus olhos e o anseio da sua alma, os seus filhos e as suas filhas,",np:1},
{v:26,t:"naquele dia um fugitivo virá até ti para te dar a notícia;"},
{v:27,t:"naquele dia a tua boca se abrirá diante do fugitivo; falarás e não ficarás mais mudo, e serás para eles um sinal; e saberão que eu sou o Senhor.",n:"Compare 3,26–27 e 33,21–22."}
];

window.TEXTOS_SEED["ezequiel"][25] = [
{s:"Contra os amonitas"},
{v:1,t:"A palavra do Senhor me foi dirigida:",n:"Os capítulos 25–32 reúnem os oráculos contra as nações vizinhas."},
{v:2,t:"Filho do homem, volta o rosto para os amonitas e profetiza contra eles."},
{v:3,l:["Dize aos amonitas: Ouvi a palavra do Senhor Deus.","Assim diz o Senhor Deus: Porque gritaste de alegria sobre o meu santuário, quando foi profanado, sobre a terra de Israel, quando foi devastada, e sobre a casa de Judá, quando foi para o exílio,"]},
{v:4,t:"por isso vou entregar-te em propriedade aos filhos do Oriente; eles estabelecerão em ti os seus acampamentos e armarão em ti as suas tendas; comerão os teus frutos e beberão o teu leite."},
{v:5,t:"Farei de Rabá uma pastagem de camelos, e dos amonitas, um curral de ovelhas; e sabereis que eu sou o Senhor."},
{v:6,t:"Pois assim diz o Senhor Deus: Porque bateste palmas e bateste com os pés, e te alegraste com todo o desprezo da tua alma pela terra de Israel,",np:1},
{v:7,t:"por isso eis que estendo a minha mão contra ti; eu te entregarei como presa às nações, te exterminarei do meio dos povos e te farei desaparecer dos países; eu te destruirei, e saberás que eu sou o Senhor."},
{s:"Contra Moab"},
{v:8,t:"Assim diz o Senhor Deus: Porque Moab e Seir disseram que a casa de Judá é como todas as nações,"},
{v:9,t:"por isso eis que abrirei o flanco de Moab, privando-o das suas cidades, das cidades das suas fronteiras, a joia da terra: Bet-Jesimot, Baal-Meon e Cariataim;"},
{v:10,t:"eu o darei em propriedade aos filhos do Oriente, junto com os amonitas, para que não se lembre mais dos amonitas entre as nações."},
{v:11,t:"Executarei os meus julgamentos em Moab, e saberão que eu sou o Senhor.",np:1},
{s:"Contra Edom"},
{v:12,t:"Assim diz o Senhor Deus: Porque Edom se vingou da casa de Judá e se tornou muito culpado vingando-se dela,"},
{v:13,t:"por isso assim diz o Senhor Deus: Estenderei a minha mão contra Edom e exterminarei dele homens e animais; farei dele um deserto; desde Temã até Dedan cairão pela espada."},
{v:14,t:"Exercerei a minha vingança contra Edom por meio do meu povo Israel; eles tratarão Edom segundo a minha ira e o meu furor, e conhecerão a minha vingança, oráculo do Senhor Deus."},
{s:"Contra os filisteus"},
{v:15,t:"Assim diz o Senhor Deus: Porque os filisteus agiram por vingança e se vingaram com desprezo na alma, para destruir, movidos por uma inimizade eterna,"},
{v:16,t:"por isso assim diz o Senhor Deus: Eis que estendo a minha mão contra os filisteus, exterminarei os cereteus e destruirei o resto do litoral;",n:"Cereteus: povo aparentado com os filisteus, talvez de origem cretense."},
{v:17,t:"executarei contra eles grandes vinganças, com castigos furiosos; e saberão que eu sou o Senhor, quando exercer contra eles a minha vingança."}
];

window.TEXTOS_SEED["ezequiel"][26] = [
{s:"Contra Tiro"},
{v:1,t:"No décimo primeiro ano, no primeiro dia do mês, a palavra do Senhor me foi dirigida:",n:"O mês não é indicado; provavelmente em 587 ou 586 antes de Cristo, logo depois da queda de Jerusalém. Tiro, cidade fenícia construída numa ilha, resistiu treze anos ao cerco de Nabucodonosor."},
{v:2,l:["Filho do homem, porque Tiro disse de Jerusalém:","Ah! Foi quebrada","a porta dos povos!","Ela se voltou para mim;","a que era cheia está deserta,"]},
{v:3,l:["por isso assim diz o Senhor Deus:","Eis que estou contra ti, Tiro,","e farei subir contra ti muitas nações,","como o mar faz subir as suas ondas;"],np:1},
{v:4,l:["elas destruirão os muros de Tiro","e derrubarão as suas torres;","rasparei dela até o pó","e farei dela uma rocha nua."],np:1,n:"No hebraico, Tiro (Tsor) significa rocha."},
{v:5,l:["Ela será um lugar para estender redes","no meio do mar,","pois eu falei,","oráculo do Senhor Deus;","e ela será saqueada pelas nações."],np:1},
{v:6,l:["As suas filhas, que estão no campo,","serão mortas pela espada,","e saberão que eu sou o Senhor."],np:1,n:"As suas filhas: as cidades dependentes de Tiro, no continente."},
{v:7,l:["Pois assim diz o Senhor Deus:","Eis que vou trazer do norte contra Tiro","Nabucodonosor, rei da Babilônia,","rei dos reis,","com cavalos, carros e cavaleiros,","com uma multidão e um grande exército."],np:1},
{v:8,l:["Ele matará à espada","as tuas filhas que estão no campo;","levantará contra ti trincheiras,","construirá ao teu redor uma rampa","e erguerá contra ti uma cobertura de escudos;"],np:1},
{v:9,l:["dirigirá contra os teus muros os seus aríetes e máquinas de guerra","e derrubará as tuas torres com as suas armas."],np:1},
{v:10,l:["A multidão dos seus cavalos","te cobrirá de poeira;","com o estrondo dos cavaleiros,","das rodas e dos carros","os teus muros tremerão,","quando ele entrar pelas tuas portas","como se entra numa cidade arrombada."],np:1},
{v:11,l:["Com os cascos dos seus cavalos","pisará todas as tuas ruas,","matará o teu povo à espada,","e as tuas colunas poderosas","cairão por terra."],np:1,n:"Colunas: talvez as estelas sagradas dos templos de Tiro."},
{v:12,l:["Saquearão as tuas riquezas,","roubarão as tuas mercadorias,","derrubarão os teus muros,","destruirão as tuas casas magníficas","e lançarão no meio das águas","as tuas pedras, a tua madeira e o teu pó."],np:1},
{v:13,l:["Farei cessar o ruído dos teus cânticos,","e o som das tuas cítaras não se ouvirá mais."],np:1},
{v:14,l:["Farei de ti uma rocha nua;","serás um lugar para estender redes;","não serás mais reconstruída,","pois eu falei,","oráculo do Senhor Deus."],np:1},
{s:"O lamento dos príncipes do mar"},
{v:15,t:"Assim diz o Senhor Deus a Tiro: Não tremerão as ilhas com o estrondo da tua queda e com o gemido dos teus feridos, quando se fizer a matança no meio de ti?"},
{v:16,t:"Todos os príncipes do mar descerão dos seus tronos, tirarão os seus mantos e despirão as suas roupas bordadas; e se vestirão de espanto, se sentarão no chão e, aterrados e trêmulos, ficarão pasmos por tua causa.",np:1},
{v:17,l:["Entoarão sobre ti uma lamentação e te dirão:","Como pereceste, tu que habitavas no mar,","cidade famosa,","que eras poderosa no mar,","tu e os teus habitantes,","que eram temidos por todos!"]},
{v:18,l:["Agora os navios ficarão pasmos","no dia da tua queda,","e as ilhas do mar se perturbarão","com o teu fim."],np:1},
{v:19,t:"Pois assim diz o Senhor Deus: Quando eu fizer de ti uma cidade desolada, como as cidades desabitadas, quando fizer subir sobre ti o abismo e as águas imensas te cobrirem,",np:1},
{v:20,t:"eu te farei descer com os que descem à cova, para junto do povo de outrora, e te farei habitar nas profundezas da terra, como as ruínas antigas, com os que descem à cova, para que não sejas mais habitada nem tenhas lugar na terra dos vivos;",n:"A cova: a morada dos mortos."},
{v:21,t:"farei de ti um nada, e deixarás de existir; serás procurada, mas nunca mais serás encontrada, oráculo do Senhor Deus."}
];

window.TEXTOS_SEED["ezequiel"][27] = [
{s:"Lamentação sobre Tiro, o navio magnífico"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,t:"Tu, pois, filho do homem, entoa uma lamentação sobre Tiro"},
{v:3,l:["e dize a Tiro, que habita à entrada do mar e comercia com os povos de muitas ilhas: Assim diz o Senhor Deus:","Tiro, tu disseste: Sou de uma beleza perfeita!"],n:"Tiro é descrita como um navio magnífico, construído com o melhor de cada país, que naufraga em alto-mar."},
{v:4,l:["As tuas fronteiras estão no coração dos mares;","os teus construtores aperfeiçoaram a tua beleza."],np:1},
{v:5,l:["Com pinheiros de Sanir","fizeram todas as tuas pranchas;","tomaram um cedro do Líbano","para fazer o teu mastro;"],np:1},
{v:6,l:["com carvalhos de Basã","fizeram os teus remos;","fizeram o teu convés de marfim","e de ciprestes das ilhas de Cetim."],np:1},
{v:7,l:["O teu velame era de linho fino bordado do Egito,","para te servir de bandeira;","a púrpura violeta e escarlate das ilhas de Elisa","era o teu toldo."],np:1},
{v:8,l:["Os habitantes de Sidônia e de Arvad","eram os teus remadores;","os teus sábios, Tiro,","eram os teus marinheiros."],np:1},
{v:9,l:["Os anciãos de Biblos e os seus sábios estavam em ti","para calafetar as tuas fendas.","Todos os navios do mar e os seus marinheiros","estavam em ti para negociar as tuas mercadorias."],np:1},
{v:10,l:["Persas, os de Lud e os de Fut","estavam no teu exército,","eram os teus guerreiros.","Penduravam em ti o escudo e o capacete;","davam-te esplendor."],np:1},
{v:11,t:"Os filhos de Arvad, com o teu exército, estavam sobre os teus muros, ao redor, e os de Gamad, nas tuas torres. Penduravam os seus escudos nos teus muros, ao redor; eles completavam a tua beleza.",np:1},
{s:"O comércio de Tiro"},
{v:12,t:"Társis comerciava contigo por causa da abundância de todas as tuas riquezas; davam prata, ferro, estanho e chumbo em troca das tuas mercadorias."},
{v:13,t:"Javã, Tubal e Mosoc negociavam contigo; traziam escravos e objetos de bronze em troca das tuas mercadorias."},
{v:14,t:"Os da casa de Togorma traziam cavalos, cavaleiros e mulos para os teus mercados;"},
{v:15,t:"os filhos de Rodes negociavam contigo; muitas ilhas eram o teu mercado: pagavam-te como tributo presas de marfim e ébano.",n:"Rodes: assim a Nova Vulgata, com a tradução grega; o hebraico diz Dedan."},
{v:16,t:"Edom comerciava contigo por causa da abundância dos teus produtos; traziam granadas, púrpura, bordados, linho fino, corais e rubis em troca das tuas mercadorias."},
{v:17,t:"Judá e a terra de Israel negociavam contigo; traziam trigo de primeira, bálsamo, mel, azeite e resina em troca."},
{v:18,t:"Damasco comerciava contigo por causa da abundância dos teus produtos e da abundância de todas as riquezas: vinho de Helbon e lã de Saar"},
{v:19,t:"e vinho de Uzal davam em troca das tuas mercadorias; ferro trabalhado, cássia e cana aromática faziam parte do teu comércio."},
{v:20,t:"Dedan negociava contigo mantas para montaria."},
{v:21,t:"A Arábia e todos os príncipes de Cedar negociavam contigo: com cordeiros, carneiros e bodes faziam comércio contigo."},
{v:22,t:"Os mercadores de Sabá e de Regma negociavam contigo; davam os melhores perfumes, toda espécie de pedras preciosas e ouro em troca das tuas mercadorias.",np:1},
{v:23,t:"Harã, Cane e Éden negociavam contigo; Sabá, a Assíria e Quelmad eram teus mercadores."},
{v:24,t:"Eles negociavam contigo roupas magníficas, mantos de púrpura violeta e bordados, tapetes multicoloridos, cordas trançadas e cedros, no teu mercado."},
{s:"O naufrágio de Tiro"},
{v:25,l:["Os navios de Társis eram os primeiros","no teu comércio;","ficaste repleta e muito gloriosa","no coração dos mares."]},
{v:26,l:["Os teus remadores te levaram","para as águas imensas;","o vento do sul te despedaçou","no coração dos mares."],np:1},
{v:27,l:["As tuas riquezas, os teus tesouros e as tuas muitas mercadorias,","os teus marinheiros e os teus pilotos,","os que calafetavam as tuas fendas e negociavam as tuas mercadorias,","todos os teus guerreiros","que estão em ti,","com toda a multidão","que está no meio de ti,","cairão no coração dos mares","no dia da tua ruína."],np:1},
{v:28,l:["Ao clamor dos teus pilotos","as praias tremerão."],np:1},
{v:29,l:["Descerão dos seus navios","todos os que manejam o remo;","os marinheiros e todos os pilotos do mar","ficarão em terra."],np:1},
{v:30,l:["Levantarão a voz sobre ti","e gritarão amargamente;","lançarão pó sobre a cabeça","e rolarão na cinza."],np:1},
{v:31,l:["Raparão a cabeça por tua causa","e se cingirão de pano de saco;","chorarão por ti com amargura na alma,","com pranto amargo;"],np:1},
{v:32,l:["entoarão sobre ti, gemendo, uma lamentação","e chorarão por ti:","Quem era como Tiro, agora silenciosa","no meio do mar?"],np:1},
{v:33,l:["Quando as tuas mercadorias chegavam pelo mar, saciavas muitos povos;","com a abundância das tuas riquezas e das tuas mercadorias","enriquecias os reis da terra."],np:1},
{v:34,l:["Agora estás despedaçada pelo mar,","nas profundezas das águas;","as tuas riquezas e toda a tua multidão,","que estava no meio de ti,","afundaram."],np:1},
{v:35,l:["Todos os habitantes das ilhas","ficaram pasmos por tua causa,","e os seus reis se arrepiaram de horror, com o rosto transtornado;"],np:1},
{v:36,l:["os mercadores dos povos assobiaram sobre ti.","Tornaste-te um objeto de horror","e deixarás de existir para sempre."],np:1}
];

window.TEXTOS_SEED["ezequiel"][28] = [
{s:"Contra o príncipe de Tiro"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,l:["Filho do homem, dize ao príncipe de Tiro: Assim diz o Senhor Deus:","Porque o teu coração se exaltou","e disseste: Eu sou um deus,","sento-me num trono divino","no coração dos mares;","sendo homem e não Deus,","igualaste o teu coração ao coração de Deus."],n:"O príncipe de Tiro: Itobaal III, que reinava no tempo do cerco babilônico."},
{v:3,l:["Eis que és mais sábio que Danel,","nenhum segredo te é oculto;"],np:1,n:"Danel: compare 14,14."},
{v:4,l:["com a tua sabedoria e a tua inteligência","adquiriste riquezas","e acumulaste ouro e prata","nos teus tesouros;"],np:1},
{v:5,l:["com a tua grande sabedoria e o teu comércio","multiplicaste as tuas riquezas,","e o teu coração se exaltou por causa das tuas riquezas."],np:1},
{v:6,t:"Por isso assim diz o Senhor Deus: Porque igualaste o teu coração ao coração de Deus,",np:1},
{v:7,l:["por isso eis que vou trazer contra ti","estrangeiros, as mais violentas das nações;","eles desembainharão as espadas contra a beleza da tua sabedoria","e profanarão o teu esplendor."],np:1},
{v:8,l:["Eles te farão descer à cova, e morrerás","da morte dos que são mortos no coração dos mares."],np:1},
{v:9,l:["Dirás ainda: Eu sou um deus,","diante dos que te matarem,","sendo homem e não Deus","nas mãos dos que te ferirem?"],np:1},
{v:10,l:["Morrerás da morte dos incircuncisos","pelas mãos de estrangeiros,","pois eu falei,","oráculo do Senhor Deus."],np:1,n:"Morrer como incircunciso era a pior desonra: ser sepultado entre os impuros."},
{s:"Lamentação sobre o rei de Tiro"},
{v:11,t:"A palavra do Senhor me foi dirigida: Filho do homem, entoa uma lamentação sobre o rei de Tiro"},
{v:12,l:["e dize-lhe: Assim diz o Senhor Deus:","Tu eras o selo da perfeição,","cheio de sabedoria e de beleza perfeita;"],n:"A lamentação descreve o rei como o primeiro homem no jardim de Deus, expulso por causa do orgulho; os Padres da Igreja aplicaram estes versículos também à queda de Satanás."},
{v:13,l:["estavas no Éden, no jardim de Deus;","toda espécie de pedras preciosas te cobria:","sárdio, topázio e jaspe,","crisólito, ônix e berilo,","safira, carbúnculo e esmeralda;","de ouro eram os teus engastes e os teus adornos;","foram preparados no dia em que foste criado."],np:1},
{v:14,l:["Eu te pus com o querubim protetor de asas estendidas;","estavas no monte santo de Deus,","andavas no meio das pedras de fogo,"],np:1,n:"Assim a Nova Vulgata, com a tradução grega; o hebraico pode ser lido: Tu eras um querubim protetor."},
{v:15,l:["perfeito nos teus caminhos","desde o dia em que foste criado,","até que se encontrou em ti a iniquidade."],np:1},
{v:16,l:["Com a abundância do teu comércio, o teu interior se encheu","de violência, e pecaste.","Por isso te expulsei do monte de Deus,","e o querubim protetor te fez perecer","do meio das pedras de fogo."],np:1},
{v:17,l:["O teu coração se exaltou por causa da tua beleza;","corrompeste a tua sabedoria por causa do teu esplendor:","eu te lancei por terra,","te expus diante dos reis, para que te vissem."],np:1},
{v:18,l:["Com a multidão das tuas iniquidades","e a desonestidade do teu comércio","profanaste os teus santuários;","por isso farei sair do meio de ti um fogo","que te devorará,","e te reduzirei a cinza sobre a terra","à vista de todos os que te veem."],np:1},
{v:19,l:["Todos os que te conhecem entre as nações","ficarão pasmos por tua causa;","tornaste-te um objeto de horror","e deixarás de existir para sempre."],np:1},
{s:"Contra Sidônia"},
{v:20,t:"A palavra do Senhor me foi dirigida:"},
{v:21,t:"Filho do homem, volta o rosto contra Sidônia e profetiza contra ela"},
{v:22,l:["e dize: Assim diz o Senhor Deus:","Eis que estou contra ti, Sidônia,","e serei glorificado no meio de ti;","e saberão que eu sou o Senhor,","quando executar nela os meus julgamentos","e manifestar nela a minha santidade."]},
{v:23,l:["Mandarei contra ela a peste","e o sangue nas suas ruas;","os mortos cairão no meio dela, pela espada que a cercará de todos os lados;","e saberão que eu sou o Senhor."],np:1},
{v:24,t:"E não haverá mais para a casa de Israel espinho que fere nem abrolho que machuca, da parte de todos os seus vizinhos que a desprezam; e saberão que eu sou o Senhor Deus.",np:1},
{s:"Israel reunido na sua terra"},
{v:25,t:"Assim diz o Senhor Deus: Quando eu reunir a casa de Israel dentre os povos por onde está dispersa, manifestarei neles a minha santidade aos olhos das nações, e eles habitarão na sua terra, a que dei ao meu servo Jacó;"},
{v:26,t:"habitarão nela em segurança, construirão casas e plantarão vinhas; habitarão em segurança, quando eu executar os meus julgamentos contra todos os seus vizinhos que os desprezam; e saberão que eu sou o Senhor, seu Deus."}
];

window.TEXTOS_SEED["ezequiel"][29] = [
{s:"Contra o faraó, o grande crocodilo"},
{v:1,t:"No décimo ano, no décimo mês, no dia doze do mês, a palavra do Senhor me foi dirigida:",n:"Em janeiro de 587 antes de Cristo, durante o cerco de Jerusalém. Os capítulos 29–32 reúnem os oráculos contra o Egito."},
{v:2,t:"Filho do homem, volta o rosto contra o faraó, rei do Egito, e profetiza contra ele e contra todo o Egito."},
{v:3,l:["Fala e dize: Assim diz o Senhor Deus:","Eis que estou contra ti, faraó,","rei do Egito,","grande crocodilo, deitado","no meio dos teus rios,","que dizes: O Nilo é meu,","e fui eu que me fiz a mim mesmo!"],n:"Crocodilo: em hebraico, tannim, o monstro das águas; a Nova Vulgata diz dragão."},
{v:4,l:["Porei ganchos nas tuas mandíbulas,","farei que os peixes dos teus rios se grudem às tuas escamas","e te tirarei do meio dos teus rios,","com todos os peixes dos teus rios grudados às tuas escamas."],np:1},
{v:5,l:["Eu te lançarei no deserto,","a ti e a todos os peixes dos teus rios;","cairás sobre a face do campo;","não serás recolhido nem sepultado.","Eu te entreguei como alimento","aos animais da terra e às aves do céu."],np:1},
{v:6,l:["E todos os habitantes do Egito saberão","que eu sou o Senhor,","porque foste um bordão de cana","para a casa de Israel:"],np:1,n:"Compare Isaías 36,6."},
{v:7,l:["quando te pegaram com a mão,","tu te quebraste e lhes rasgaste o ombro;","quando se apoiaram em ti,","tu te partiste","e fizeste vacilar os seus rins."],np:1},
{v:8,t:"Por isso assim diz o Senhor Deus: Eis que vou fazer vir contra ti a espada e exterminarei de ti homens e animais;",np:1},
{v:9,t:"a terra do Egito se tornará um deserto e uma desolação; e saberão que eu sou o Senhor. Porque disseste: O Nilo é meu, e fui eu que o fiz,"},
{v:10,t:"por isso eis que estou contra ti e contra os teus rios; farei da terra do Egito uma desolação completa, arrasada pela espada, desde Magdol até Siene e até a fronteira da Etiópia.",n:"De Magdol, no norte, até Siene, a atual Assuã, no sul: o Egito inteiro."},
{v:11,t:"Nenhum pé de homem passará por ela, nem pé de animal andará por ela, e ela ficará desabitada durante quarenta anos."},
{v:12,t:"Farei da terra do Egito um deserto no meio das terras desertas, e as suas cidades ficarão desoladas no meio das cidades arruinadas durante quarenta anos; e dispersarei os egípcios entre as nações e os espalharei pelos países."},
{v:13,t:"Pois assim diz o Senhor Deus: Ao fim de quarenta anos, reunirei os egípcios dentre os povos por onde tiverem sido dispersos;",np:1},
{v:14,t:"mudarei a sorte do Egito e os farei voltar à terra de Patros, a terra da sua origem; e ali serão um reino humilde."},
{v:15,t:"Será o mais humilde dos reinos e não se elevará mais acima das nações; eu os tornarei pequenos, para que não dominem as nações."},
{v:16,t:"E não serão mais objeto de confiança para a casa de Israel, que lhe trariam à memória a iniquidade de se voltar para eles; e saberão que eu sou o Senhor Deus."},
{s:"O Egito, salário de Nabucodonosor"},
{v:17,t:"No vigésimo sétimo ano, no primeiro mês, no primeiro dia do mês, a palavra do Senhor me foi dirigida:",n:"Em abril de 571 antes de Cristo: é a data mais tardia do livro."},
{v:18,t:"Filho do homem, Nabucodonosor, rei da Babilônia, fez o seu exército trabalhar duramente contra Tiro; todas as cabeças ficaram calvas e todos os ombros esfolados; mas nem ele nem o seu exército receberam de Tiro salário pelo trabalho que fizeram contra ela.",n:"Depois de treze anos de cerco, Tiro se rendeu por acordo, sem ser saqueada; compare 26,7–14."},
{v:19,t:"Por isso assim diz o Senhor Deus: Eis que vou dar a Nabucodonosor, rei da Babilônia, a terra do Egito; ele levará as suas riquezas, saqueará os seus despojos e tomará a sua presa: esse será o salário do seu exército,",np:1},
{v:20,t:"a paga pelo trabalho que fez contra ela. Eu lhe dou a terra do Egito, porque trabalharam para mim, oráculo do Senhor Deus."},
{v:21,t:"Naquele dia farei brotar um chifre para a casa de Israel e abrirei a tua boca no meio deles; e saberão que eu sou o Senhor.",n:"O chifre: símbolo de força; talvez um anúncio messiânico (compare Salmo 132,17)."}
];

window.TEXTOS_SEED["ezequiel"][30] = [
{s:"O dia do Senhor contra o Egito"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,l:["Filho do homem, profetiza e dize: Assim diz o Senhor Deus:","Gemei: Ai daquele dia!"]},
{v:3,l:["Pois está perto o dia,","aproxima-se o dia do Senhor,","dia de nuvens; será o tempo das nações."],np:1},
{v:4,l:["A espada virá contra o Egito,","e haverá terror na Etiópia,","quando caírem os feridos no Egito,","quando levarem as suas riquezas","e forem destruídos os seus alicerces."],np:1},
{v:5,l:["A Etiópia, Fut e Lud, toda a gente de raças misturadas,","Cub e os filhos da terra da aliança","cairão com eles pela espada."],np:1,n:"Povos aliados ou mercenários do Egito; Cub é desconhecido, e os filhos da terra da aliança são talvez os judeus refugiados no Egito."},
{v:6,l:["Assim diz o Senhor Deus:","Cairão os que apoiam o Egito,","e o orgulho do seu poder será abatido;","desde Magdol até Siene cairão pela espada,","oráculo do Senhor Deus."],np:1},
{v:7,t:"Serão devastados no meio dos países desolados, e as suas cidades estarão no meio das cidades desertas;",np:1},
{v:8,t:"e saberão que eu sou o Senhor, quando eu puser fogo no Egito e todos os que o ajudam forem esmagados."},
{v:9,t:"Naquele dia sairão mensageiros da minha parte, em navios, para aterrorizar a Etiópia confiante; e haverá entre eles terror no dia do Egito; pois eis que ele vem.",np:1},
{v:10,t:"Assim diz o Senhor Deus: Farei cessar a multidão do Egito pela mão de Nabucodonosor, rei da Babilônia.",np:1},
{v:11,t:"Ele e o seu povo com ele, os mais violentos das nações, serão trazidos para destruir a terra; desembainharão as espadas contra o Egito e encherão a terra de mortos."},
{v:12,t:"Secarei os canais do Nilo e entregarei a terra nas mãos de homens maus; devastarei a terra e tudo o que ela contém pela mão de estrangeiros. Eu, o Senhor, falei."},
{v:13,l:["Assim diz o Senhor Deus:","Destruirei os ídolos","e farei desaparecer de Mênfis os falsos deuses;","não haverá mais príncipe","na terra do Egito,","e espalharei o terror na terra do Egito."],np:1},
{v:14,l:["Devastarei a terra de Patros,","porei fogo em Tânis","e executarei os meus julgamentos em Nô."],np:1},
{v:15,t:"Derramarei o meu furor sobre Sin, a fortaleza do Egito, e exterminarei a multidão de Nô.",np:1,n:"Sin: Pelúsio, fortaleza na fronteira oriental do Egito; Nô é Tebas (compare Jeremias 46,25)."},
{v:16,t:"Porei fogo no Egito; Sin se contorcerá de dor como a mulher que dá à luz, Nô será arrombada, e Mênfis terá inimigos em pleno dia."},
{v:17,t:"Os jovens de Heliópolis e de Bubástis cairão pela espada, e as próprias cidades irão para o cativeiro."},
{v:18,t:"Em Táfnis o dia escurecerá, quando eu quebrar ali os cetros do Egito e acabar nela o orgulho do seu poder; uma nuvem a cobrirá, e as suas filhas irão para o cativeiro."},
{v:19,t:"Executarei os meus julgamentos no Egito, e saberão que eu sou o Senhor."},
{s:"O braço quebrado do faraó"},
{v:20,t:"No décimo primeiro ano, no primeiro mês, no dia sete do mês, a palavra do Senhor me foi dirigida:",n:"Em abril de 587 antes de Cristo, depois do fracasso do exército egípcio que tentara socorrer Jerusalém (Jeremias 37,5–11)."},
{v:21,t:"Filho do homem, quebrei o braço do faraó, rei do Egito, e eis que não foi enfaixado para ser curado, nem envolvido em ataduras e faixas, para que recobre a força e possa empunhar a espada."},
{v:22,t:"Por isso assim diz o Senhor Deus: Eis que estou contra o faraó, rei do Egito; quebrarei os seus braços, o que está forte e o que já está quebrado, e farei cair a espada da sua mão."},
{v:23,t:"Dispersarei os egípcios entre as nações e os espalharei pelos países."},
{v:24,t:"Fortalecerei os braços do rei da Babilônia e porei a minha espada na sua mão; mas quebrarei os braços do faraó, e ele gemerá diante dele como gemem os feridos de morte.",np:1},
{v:25,t:"Fortalecerei os braços do rei da Babilônia, e os braços do faraó cairão; e saberão que eu sou o Senhor, quando puser a minha espada na mão do rei da Babilônia e ele a estender contra a terra do Egito."},
{v:26,t:"Dispersarei os egípcios entre as nações e os espalharei pelos países; e saberão que eu sou o Senhor."}
];

window.TEXTOS_SEED["ezequiel"][31] = [
{s:"O faraó, cedro gigantesco"},
{v:1,t:"No décimo primeiro ano, no terceiro mês, no primeiro dia do mês, a palavra do Senhor me foi dirigida:",n:"Em junho de 587 antes de Cristo."},
{v:2,l:["Filho do homem, dize ao faraó, rei do Egito, e à sua multidão:","A quem és semelhante na tua grandeza?"]},
{v:3,l:["Eis um abeto, como um cedro do Líbano,","de belos ramos e de folhagem espessa,","de grande altura,","e a sua copa se elevava entre as nuvens;"],np:1,n:"Um abeto: assim a Nova Vulgata, com uma leitura do hebraico; o texto tradicional diz: a Assíria era um cedro no Líbano."},
{v:4,l:["as águas o fizeram crescer,","o abismo o elevou;","os seus rios corriam","ao redor das suas raízes,","e ele enviava os seus canais","a todas as árvores do campo."],np:1},
{v:5,l:["Por isso a sua altura se elevou","acima de todas as árvores do campo;","os seus galhos se multiplicaram,","e os seus ramos se estenderam","por causa das águas abundantes."],np:1},
{v:6,l:["Quando estendia a sua sombra,","todas as aves do céu","faziam ninho nos seus ramos,","todos os animais do campo","davam cria debaixo da sua folhagem,","e à sua sombra habitava","a multidão de todas as nações;"],np:1},
{v:7,l:["era belíssimo na sua grandeza","e na extensão dos seus ramos,","pois a sua raiz estava","junto de águas abundantes."],np:1},
{v:8,l:["Os cedros não o igualavam","no jardim de Deus;","os abetos não se comparavam","aos seus ramos,","e os plátanos não eram","como a sua folhagem;","nenhuma árvore do jardim de Deus","se lhe assemelhava na beleza,"],np:1},
{v:9,l:["pois eu o tinha feito belo,","com a sua folhagem abundante e espessa,","e todas as árvores do Éden,","que estavam no jardim de Deus, lhe tinham inveja."],np:1},
{s:"A queda do cedro"},
{v:10,t:"Por isso assim diz o Senhor Deus: Porque se elevou na sua altura, levantou a sua copa até as nuvens e o seu coração se exaltou com a sua altura,"},
{v:11,t:"eu o entregarei nas mãos do mais poderoso das nações, que o tratará como merece: por causa da sua impiedade eu o expulsei."},
{v:12,t:"Estrangeiros, os mais violentos das nações, o cortarão e o abandonarão sobre os montes; os seus ramos cairão em todos os vales, e os seus galhos se quebrarão em todas as ravinas da terra; todos os povos da terra se retirarão da sua sombra e o abandonarão."},
{v:13,l:["Sobre as suas ruínas habitarão","todas as aves do céu,","e nos seus ramos estarão","todos os animais do campo,"],np:1},
{v:14,l:["para que nenhuma das árvores junto às águas se eleve na sua altura,","nem levante a sua copa entre as nuvens,","e para que nenhuma das que bebem água","se mantenha de pé na sua altura; pois","todas foram entregues à morte,","às profundezas da terra,","no meio dos filhos dos homens,","com os que descem à cova."],np:1},
{v:15,t:"Assim diz o Senhor Deus: No dia em que ele desceu à morada dos mortos, mandei o luto, cobri por causa dele o abismo, detive os seus rios, e as águas abundantes pararam; cobri de luto o Líbano por causa dele, e todas as árvores do campo desfaleceram.",np:1},
{v:16,t:"Com o estrondo da sua queda fiz tremer as nações, quando o fiz descer à morada dos mortos com os que descem à cova; e todas as árvores do Éden, as melhores e mais belas do Líbano, todas as que bebiam água, se consolaram nas profundezas da terra."},
{v:17,t:"Pois também elas desceram com ele à morada dos mortos, para junto dos que foram mortos à espada, com os que o apoiavam e habitavam à sua sombra no meio das nações.",np:1},
{v:18,t:"A quem és semelhante, tu, tão glorioso e tão alto entre as árvores do Éden? Eis que foste precipitado, com as árvores do Éden, às profundezas da terra; jazerás no meio dos incircuncisos, com os que foram mortos à espada. Este é o faraó com toda a sua multidão, oráculo do Senhor Deus.",np:1}
];

window.TEXTOS_SEED["ezequiel"][32] = [
{s:"Lamentação sobre o faraó"},
{v:1,t:"No décimo segundo ano, no décimo segundo mês, no primeiro dia do mês, a palavra do Senhor me foi dirigida:",n:"Em março de 585 antes de Cristo."},
{v:2,l:["Filho do homem, entoa uma lamentação sobre o faraó, rei do Egito, e dize-lhe:","Leão das nações, pereceste;","eras como o monstro no mar;","agitavas os teus rios,","turvavas as águas com os pés","e enlameavas os seus rios."]},
{v:3,l:["Assim diz o Senhor Deus:","Estenderei sobre ti a minha rede","numa assembleia de muitos povos,","e eles te puxarão na minha rede;"],np:1},
{v:4,l:["eu te lançarei por terra,","te arremessarei sobre a face do campo,","farei pousar sobre ti todas as aves do céu","e saciarei de ti os animais de toda a terra;"],np:1},
{v:5,l:["espalharei a tua carne sobre os montes","e encherei os vales com os teus restos podres."],np:1},
{v:6,l:["Regarei a terra com o fedor","do teu sangue, até os montes,","e as ravinas se encherão de ti;"],np:1},
{v:7,l:["quando te apagares, cobrirei o céu","e escurecerei as suas estrelas;","cobrirei o sol com uma nuvem,","e a lua não dará a sua luz;"],np:1},
{v:8,l:["farei que todos os astros do céu","se vistam de luto por tua causa","e espalharei as trevas sobre a tua terra,","oráculo do Senhor Deus."],np:1},
{v:9,t:"Perturbarei o coração de muitos povos, quando fizer chegar a notícia da tua ruína entre as nações, a países que não conheces.",np:1},
{v:10,t:"Deixarei pasmos por tua causa muitos povos, e os seus reis se arrepiarão de horror por tua causa, quando eu brandir a minha espada diante deles; cada um tremerá sem cessar pela própria vida, no dia da tua queda."},
{v:11,t:"Pois assim diz o Senhor Deus: A espada do rei da Babilônia virá contra ti;"},
{v:12,l:["com as espadas dos valentes farei cair a tua multidão;","são todos os mais violentos das nações;","eles devastarão o orgulho do Egito,","e toda a sua multidão será destruída."],np:1},
{v:13,l:["Exterminarei todos os seus animais","que estavam junto às águas abundantes;","o pé do homem não as turvará mais,","nem os cascos dos animais as enlamearão;"],np:1},
{v:14,l:["então farei que as suas águas fiquem límpidas","e que os seus rios corram como o azeite,","oráculo do Senhor Deus."],np:1},
{v:15,l:["Quando eu fizer da terra do Egito uma desolação,","e a terra ficar despojada de tudo o que a enche, quando eu ferir todos os seus habitantes,","saberão que eu sou o Senhor."],np:1},
{v:16,t:"Esta é uma lamentação, e a entoarão; as filhas das nações a entoarão; sobre o Egito e sobre toda a sua multidão a entoarão, oráculo do Senhor Deus.",np:1},
{s:"O Egito desce à morada dos mortos"},
{v:17,t:"No décimo segundo ano, no dia quinze do mês, a palavra do Senhor me foi dirigida:",n:"O mês não é indicado; provavelmente o mesmo do v. 1."},
{v:18,t:"Filho do homem, entoa um lamento sobre a multidão do Egito e faze-a descer, ela e as filhas das nações poderosas, às profundezas da terra, com os que descem à cova."},
{v:19,l:["Serás tu mais belo do que os outros?","Desce e deita-te com os incircuncisos."],np:1},
{v:20,t:"Cairão no meio dos que foram mortos à espada; a espada foi entregue; arrastaram o Egito com toda a sua multidão.",np:1},
{v:21,l:["Os mais poderosos dos valentes, com os seus aliados, lhe falarão do meio da morada dos mortos, para onde desceram:","Calaram-se os incircuncisos, mortos à espada!"]},
{v:22,t:"Ali está a Assíria com toda a sua multidão; os seus sepulcros estão ao redor dela; todos foram mortos, caíram pela espada;",np:1},
{v:23,t:"os seus sepulcros foram colocados no mais profundo da cova, e a sua multidão está ao redor do seu sepulcro; todos mortos, caídos pela espada, eles que outrora espalhavam o terror na terra dos vivos."},
{v:24,t:"Ali está Elam com toda a sua multidão, ao redor do seu sepulcro; todos foram mortos, caíram pela espada; desceram incircuncisos às profundezas da terra, eles que espalhavam o terror na terra dos vivos; e carregam a sua vergonha com os que descem à cova.",np:1},
{v:25,t:"No meio dos mortos lhe puseram um leito, com toda a sua multidão, e os seus sepulcros ao seu redor; todos são incircuncisos, mortos à espada; pois tinham espalhado o seu terror na terra dos vivos e carregam a sua vergonha com os que descem à cova; foram postos no meio dos mortos."},
{v:26,t:"Ali estão Mosoc e Tubal com toda a sua multidão, e os seus sepulcros ao seu redor; todos são incircuncisos, mortos à espada, porque espalharam o seu terror na terra dos vivos;",np:1},
{v:27,t:"e não jazem com os valentes que caíram nos tempos antigos e desceram à morada dos mortos com as suas armas de guerra, cujas espadas foram postas debaixo da cabeça, e os escudos sobre os ossos, porque eram o terror dos valentes na terra dos vivos."},
{v:28,t:"Também tu serás esmagado no meio dos incircuncisos e jazerás com os que foram mortos à espada."},
{v:29,t:"Ali está Edom, com os seus reis e todos os seus príncipes, que, apesar da sua força, foram postos com os mortos à espada; jazem com os incircuncisos e com os que descem à cova.",np:1},
{v:30,t:"Ali estão todos os príncipes do norte e todos os sidônios, que desceram com os mortos, apesar do terror que espalhavam, envergonhados da sua força; jazem incircuncisos com os mortos à espada e carregam a sua vergonha com os que descem à cova.",np:1},
{v:31,t:"O faraó os verá e se consolará de toda a sua multidão: o faraó e todo o seu exército, mortos à espada, oráculo do Senhor Deus,",np:1},
{v:32,t:"pois espalhei o meu terror na terra dos vivos; e ele jazerá no meio dos incircuncisos, com os que foram mortos à espada, o faraó e toda a sua multidão, oráculo do Senhor Deus."}
];

window.TEXTOS_SEED["ezequiel"][33] = [
{s:"O profeta, sentinela de Israel"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,t:"Filho do homem, fala aos filhos do teu povo e dize-lhes: Quando eu fizer vir a espada contra uma terra, e o povo dessa terra tomar um homem do seu meio e o puser como sentinela,"},
{v:3,t:"e ele vir a espada que vem contra a terra, tocar a trombeta e avisar o povo,"},
{v:4,t:"então, se alguém ouvir o som da trombeta e não se precaver, e a espada vier e o apanhar, o seu sangue cairá sobre a sua própria cabeça;"},
{v:5,t:"ouviu o som da trombeta e não se precaveu: o seu sangue cairá sobre ele. Se tivesse se precavido, teria salvado a vida."},
{v:6,t:"Mas, se a sentinela vir a espada que vem e não tocar a trombeta, e o povo não for avisado, e a espada vier e tirar a vida de alguém, este será levado pela sua iniquidade, mas eu pedirei contas do seu sangue à sentinela."},
{v:7,t:"Quanto a ti, filho do homem, eu te constituí sentinela para a casa de Israel; quando ouvires uma palavra da minha boca, tu os advertirás da minha parte.",np:1},
{v:8,t:"Se eu disser ao ímpio: Ímpio, certamente morrerás, e tu não falares para advertir o ímpio do seu caminho, esse ímpio morrerá pela sua iniquidade, mas eu pedirei contas do seu sangue a ti."},
{v:9,t:"Mas, se advertires o ímpio para que se converta do seu caminho, e ele não se converter do seu caminho, ele morrerá pela sua iniquidade, mas tu terás salvado a tua vida.",n:"Compare 3,16–21."},
{s:"Por que haveis de morrer?"},
{v:10,t:"Tu, pois, filho do homem, dize à casa de Israel: Vós falais assim: As nossas transgressões e os nossos pecados pesam sobre nós, e por causa deles vamos definhando; como poderemos viver?"},
{v:11,t:"Dize-lhes: Pela minha vida, oráculo do Senhor Deus, não tenho prazer na morte do ímpio, mas em que o ímpio se converta do seu caminho e viva. Convertei-vos, convertei-vos dos vossos maus caminhos! Por que haveríeis de morrer, casa de Israel?"},
{v:12,t:"Tu, pois, filho do homem, dize aos filhos do teu povo: A justiça do justo não o livrará no dia em que ele pecar; e a impiedade do ímpio não o fará cair no dia em que ele se converter da sua impiedade; e o justo não poderá viver pela sua justiça no dia em que pecar.",np:1},
{v:13,t:"Ainda que eu diga ao justo que certamente viverá, se ele, confiando na sua justiça, praticar a iniquidade, nenhuma das suas obras justas será lembrada, e ele morrerá pela iniquidade que praticou."},
{v:14,t:"E, se eu disser ao ímpio: Certamente morrerás, e ele se converter do seu pecado e praticar o direito e a justiça,"},
{v:15,t:"se esse ímpio devolver o penhor, restituir o que roubou, andar nos preceitos que dão a vida e não praticar nenhuma injustiça, certamente viverá; não morrerá;"},
{v:16,t:"nenhum dos pecados que cometeu será lembrado contra ele: praticou o direito e a justiça; certamente viverá."},
{v:17,t:"E os filhos do teu povo dizem: O caminho do Senhor não é justo; mas é o caminho deles que não é justo.",np:1},
{v:18,t:"Quando o justo se afasta da sua justiça e pratica a iniquidade, morrerá por causa dela;"},
{v:19,t:"e, quando o ímpio se afasta da sua impiedade e pratica o direito e a justiça, viverá por causa disso."},
{v:20,t:"E vós dizeis: O caminho do Senhor não é reto. Eu julgarei cada um de vós segundo os seus caminhos, casa de Israel."},
{s:"A notícia da queda de Jerusalém"},
{v:21,t:"No décimo segundo ano da nossa deportação, no décimo mês, no dia cinco do mês, chegou até mim um fugitivo de Jerusalém, que disse: A cidade foi tomada.",n:"Em janeiro de 585 antes de Cristo, cerca de seis meses depois da queda da cidade."},
{v:22,t:"Na tarde anterior à chegada do fugitivo, a mão do Senhor tinha estado sobre mim; e ele abriu a minha boca antes que o fugitivo chegasse de manhã; a minha boca se abriu, e eu não fiquei mais mudo.",np:1,n:"Compare 3,26–27; 24,25–27."},
{v:23,t:"A palavra do Senhor me foi dirigida:"},
{v:24,t:"Filho do homem, os que habitam naquelas ruínas, na terra de Israel, dizem: Abraão era um só e recebeu a terra em herança; nós somos muitos: a terra nos foi dada em propriedade."},
{v:25,t:"Por isso dize-lhes: Assim diz o Senhor Deus: Vós comeis carne com sangue, levantais os olhos para os vossos ídolos e derramais sangue, e haveis de possuir a terra?"},
{v:26,t:"Apoiais-vos na espada, cometeis abominações, cada um desonra a mulher do seu próximo, e haveis de possuir a terra?"},
{v:27,t:"Dize-lhes assim: Assim diz o Senhor Deus: Pela minha vida, os que estão nas ruínas cairão pela espada; o que está no campo, eu o entregarei às feras para ser devorado; e os que estão nas fortalezas e nas cavernas morrerão de peste."},
{v:28,t:"Farei da terra uma desolação e um deserto; acabará o orgulho do seu poder, e os montes de Israel ficarão tão desolados que ninguém passará por eles;"},
{v:29,t:"e saberão que eu sou o Senhor, quando eu fizer da terra uma desolação e um deserto, por causa de todas as abominações que cometeram."},
{s:"Ouvintes que não praticam"},
{v:30,t:"Quanto a ti, filho do homem, os filhos do teu povo falam de ti junto aos muros e às portas das casas, e dizem uns aos outros, cada um ao seu irmão: Vinde ouvir qual é a palavra que vem do Senhor."},
{v:31,t:"E vêm a ti como vem uma multidão, e o meu povo se senta diante de ti; ouvem as tuas palavras, mas não as praticam; com a boca demonstram amor, mas o seu coração vai atrás do lucro."},
{v:32,t:"E tu és para eles como uma canção de amor, cantada com bela voz e com o doce som das cordas; ouvem as tuas palavras, mas não as praticam."},
{v:33,t:"Mas, quando isso acontecer — e eis que está acontecendo —, saberão que houve um profeta no meio deles."}
];

window.TEXTOS_SEED["ezequiel"][34] = [
{s:"Os maus pastores"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,t:"Filho do homem, profetiza contra os pastores de Israel; profetiza e dize aos pastores: Assim diz o Senhor Deus: Ai dos pastores de Israel, que apascentam a si mesmos! Não são as ovelhas que os pastores devem apascentar?",n:"Os pastores: os reis e chefes do povo. Compare Jeremias 23,1–6; João 10,1–18."},
{v:3,t:"Vós bebeis o leite, vos vestis com a lã e matais as ovelhas gordas, mas não apascentais o rebanho."},
{v:4,t:"Não fortalecestes a fraca, não curastes a doente, não enfaixastes a ferida, não reconduzistes a desgarrada, não procurastes a perdida; mas as dominastes com dureza e violência."},
{v:5,t:"E elas se dispersaram por falta de pastor e se tornaram presa de todas as feras do campo; dispersaram-se."},
{v:6,t:"As minhas ovelhas andam errantes por todos os montes e por todas as colinas elevadas; as minhas ovelhas estão dispersas por toda a face da terra, e não há ninguém que se preocupe com elas, ninguém que as procure."},
{v:7,t:"Por isso, pastores, ouvi a palavra do Senhor:",np:1},
{v:8,t:"Pela minha vida, oráculo do Senhor Deus, porque as minhas ovelhas se tornaram presa e alimento de todas as feras do campo, por falta de pastor, e porque os meus pastores não procuraram as minhas ovelhas, mas apascentavam a si mesmos e não apascentavam as minhas ovelhas,"},
{v:9,t:"por isso, pastores, ouvi a palavra do Senhor."},
{v:10,t:"Assim diz o Senhor Deus: Eis que estou contra os pastores: pedirei contas das minhas ovelhas às suas mãos e farei que deixem de apascentar o rebanho; os pastores não apascentarão mais a si mesmos; livrarei as minhas ovelhas da sua boca, e elas não lhes servirão mais de alimento."},
{s:"O Senhor, bom pastor"},
{v:11,t:"Pois assim diz o Senhor Deus: Eis que eu mesmo procurarei as minhas ovelhas e cuidarei delas."},
{v:12,t:"Como o pastor cuida do seu rebanho quando está no meio das suas ovelhas dispersas, assim cuidarei das minhas ovelhas e as livrarei de todos os lugares por onde foram dispersas no dia das nuvens e da escuridão."},
{v:13,t:"Eu as tirarei dentre os povos, as reunirei dos países e as levarei para a sua terra; eu as apascentarei nos montes de Israel, junto aos riachos e em todos os lugares habitados da terra."},
{v:14,t:"Eu as apascentarei em pastagens excelentes, e o seu pasto estará nos altos montes de Israel; ali repousarão em boas pastagens e se alimentarão em pastos férteis sobre os montes de Israel."},
{v:15,t:"Eu mesmo apascentarei as minhas ovelhas e eu mesmo as farei repousar, oráculo do Senhor Deus."},
{v:16,t:"Procurarei a que estava perdida, reconduzirei a desgarrada, enfaixarei a ferida, fortalecerei a doente; e guardarei a gorda e a forte; eu as apascentarei com justiça.",n:"Guardarei: assim a Nova Vulgata, com a tradução grega; o hebraico diz: destruirei."},
{s:"O julgamento entre ovelha e ovelha"},
{v:17,t:"Quanto a vós, meu rebanho, assim diz o Senhor Deus: Eis que vou julgar entre ovelha e ovelha, entre carneiros e bodes."},
{v:18,t:"Não vos bastava pastar em boa pastagem, para pisardes com os pés o resto das vossas pastagens? E, depois de beber a água mais límpida, turváveis com os pés o resto?"},
{v:19,t:"E as minhas ovelhas tinham de pastar o que os vossos pés tinham pisado e beber o que os vossos pés tinham turvado."},
{v:20,t:"Por isso assim lhes diz o Senhor Deus: Eis que eu mesmo vou julgar entre a ovelha gorda e a magra.",np:1},
{v:21,t:"Porque empurrastes com o flanco e com o ombro e chifrastes com os vossos chifres todas as ovelhas fracas, até dispersá-las para fora,"},
{v:22,t:"eu salvarei as minhas ovelhas, e elas não serão mais presa; e julgarei entre ovelha e ovelha."},
{s:"O novo Davi e a aliança de paz"},
{v:23,t:"Suscitarei para elas um único pastor, que as apascentará: o meu servo Davi; ele as apascentará e será o seu pastor.",n:"Davi: um descendente de Davi, o Messias (compare Jeremias 23,5; 30,9; João 10,11)."},
{v:24,t:"Eu, o Senhor, serei o seu Deus, e o meu servo Davi será príncipe no meio deles. Eu, o Senhor, falei."},
{v:25,t:"Farei com elas uma aliança de paz e farei desaparecer da terra as feras; habitarão em segurança no deserto e dormirão nas florestas."},
{v:26,t:"Farei delas e dos arredores da minha colina uma bênção; farei cair a chuva no seu tempo: serão chuvas de bênção."},
{v:27,t:"As árvores do campo darão o seu fruto, e a terra dará o seu produto; estarão seguras na sua terra, e saberão que eu sou o Senhor, quando eu quebrar as varas do seu jugo e as livrar da mão dos que as escravizavam.",np:1},
{v:28,t:"Não serão mais presa das nações, e as feras da terra não as devorarão; habitarão em segurança, sem que ninguém as amedronte."},
{v:29,t:"Farei brotar para elas um rebento famoso; não serão mais consumidas pela fome na terra, nem carregarão mais o insulto das nações;",n:"Um rebento famoso: assim a Nova Vulgata; o hebraico diz: uma plantação famosa."},
{v:30,t:"e saberão que eu, o Senhor, seu Deus, estou com eles, e que eles, a casa de Israel, são o meu povo, oráculo do Senhor Deus."},
{v:31,t:"Vós sois o meu rebanho, o rebanho do meu pasto, e eu sou o Senhor, vosso Deus, oráculo do Senhor Deus."}
];

window.TEXTOS_SEED["ezequiel"][35] = [
{s:"Contra o monte Seir"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,t:"Filho do homem, volta o rosto contra o monte Seir, profetiza contra ele e dize-lhe:",n:"O monte Seir: Edom."},
{v:3,l:["Assim diz o Senhor Deus:","Eis que estou contra ti, monte Seir;","estenderei a minha mão contra ti","e farei de ti uma desolação e um deserto."]},
{v:4,l:["Arrasarei as tuas cidades,","e tu te tornarás um deserto,","e saberás que eu sou o Senhor."],np:1},
{v:5,t:"Porque tiveste uma inimizade eterna e entregaste os filhos de Israel ao poder da espada no tempo da sua desgraça, no tempo do castigo final,",np:1},
{v:6,t:"por isso, pela minha vida, oráculo do Senhor Deus, eu te entregarei ao sangue, e o sangue te perseguirá; porque não odiaste o sangue, o sangue te perseguirá."},
{v:7,t:"Farei do monte Seir uma desolação e um deserto, e exterminarei dele quem vai e quem vem;"},
{v:8,t:"encherei os seus montes de mortos; nas tuas colinas, nos teus vales e em todas as tuas ravinas cairão os mortos pela espada."},
{v:9,t:"Farei de ti uma desolação perpétua, e as tuas cidades não serão habitadas; e sabereis que eu sou o Senhor."},
{v:10,t:"Porque disseste: As duas nações e os dois países serão meus, e eu os possuirei, embora o Senhor estivesse ali,",np:1,n:"As duas nações: Israel e Judá; Edom quis apoderar-se da terra de Israel depois da destruição de Jerusalém."},
{v:11,t:"por isso, pela minha vida, oráculo do Senhor Deus, agirei segundo a tua ira e segundo o ciúme com que os trataste por causa do teu ódio contra eles, e me darei a conhecer por meio deles, quando te julgar."},
{v:12,t:"E saberás que eu, o Senhor, ouvi todos os insultos que disseste contra os montes de Israel, quando dizias: Estão desolados, foram-nos dados para os devorarmos!"},
{v:13,t:"Vós vos exaltastes contra mim com a vossa boca e multiplicastes contra mim as vossas palavras; eu ouvi."},
{v:14,t:"Assim diz o Senhor Deus: Enquanto toda a terra se alegra, farei de ti uma desolação;",np:1},
{v:15,t:"como te alegraste com a herança da casa de Israel, porque foi devastada, assim farei contigo: serás devastado, monte Seir, e Edom inteiro; e saberão que eu sou o Senhor."}
];

window.TEXTOS_SEED["ezequiel"][36] = [
{s:"Os montes de Israel voltarão a florescer"},
{v:1,t:"E tu, filho do homem, profetiza aos montes de Israel e dize: Montes de Israel, ouvi a palavra do Senhor."},
{v:2,t:"Assim diz o Senhor Deus: Porque o inimigo disse de vós, com alegria, que as alturas eternas lhe foram dadas em herança,",np:1},
{v:3,t:"por isso profetiza e dize: Assim diz o Senhor Deus: Porque fostes devastados e cobiçados de todos os lados, para vos tornardes propriedade das outras nações, e fostes objeto dos comentários e dos insultos do povo,"},
{v:4,t:"por isso, montes de Israel, ouvi a palavra do Senhor Deus: Assim diz o Senhor Deus aos montes e às colinas, às ravinas e aos vales, às ruínas desoladas e às cidades abandonadas, que foram saqueadas e escarnecidas pelas outras nações ao redor;"},
{v:5,t:"por isso assim diz o Senhor Deus: No fogo do meu ciúme falei contra as outras nações e contra todo o Edom, que se apoderaram da minha terra com a alegria de todo o coração e com desprezo na alma, para saquear as suas pastagens."},
{v:6,t:"Por isso profetiza a respeito da terra de Israel e dize aos montes e às colinas, às ravinas e aos vales: Assim diz o Senhor Deus: Eis que falei no meu ciúme e no meu furor, porque suportastes a vergonha das nações;"},
{v:7,t:"por isso assim diz o Senhor Deus: Levantei a mão, jurando: as nações que estão ao vosso redor carregarão elas mesmas a sua vergonha;"},
{v:8,t:"mas vós, montes de Israel, produzireis os vossos ramos e dareis o vosso fruto ao meu povo Israel, pois está perto a sua volta."},
{v:9,t:"Pois eis que estou por vós e me voltarei para vós; sereis lavrados e semeados;"},
{v:10,t:"multiplicarei sobre vós os homens, toda a casa de Israel; as cidades serão habitadas, e as ruínas, reconstruídas."},
{v:11,t:"Multiplicarei sobre vós homens e animais, e eles se multiplicarão e serão fecundos; eu vos farei habitados como antigamente e vos farei mais bem do que no princípio; e sabereis que eu sou o Senhor."},
{v:12,t:"Farei andar sobre vós homens, o meu povo Israel; eles te possuirão, e tu serás a sua herança, e não os deixarás mais sem filhos."},
{v:13,t:"Assim diz o Senhor Deus: Porque dizem de ti: Tu devoras os homens e deixas o teu povo sem filhos,",np:1},
{v:14,t:"por isso não devorarás mais os homens e não deixarás mais o teu povo sem filhos, oráculo do Senhor Deus."},
{v:15,t:"Não farei mais ouvir em ti o insulto das nações, não carregarás mais o escárnio dos povos e não deixarás mais o teu povo sem filhos, oráculo do Senhor Deus."},
{s:"Por causa do meu santo nome"},
{v:16,t:"A palavra do Senhor me foi dirigida:"},
{v:17,t:"Filho do homem, quando a casa de Israel habitava na sua terra, contaminou-a com o seu procedimento e com as suas ações; o seu procedimento era diante de mim como a impureza de uma mulher na menstruação."},
{v:18,t:"Então derramei sobre eles o meu furor, por causa do sangue que derramaram sobre a terra e dos ídolos com que a contaminaram.",np:1},
{v:19,t:"Eu os dispersei entre as nações, e eles foram espalhados pelos países; eu os julguei segundo o seu procedimento e as suas ações."},
{v:20,t:"E, chegando às nações para onde foram, profanaram o meu santo nome, pois se dizia deles: Este é o povo do Senhor, e tiveram de sair da sua terra.",np:1},
{v:21,t:"Mas eu tive compaixão do meu santo nome, que a casa de Israel profanava entre as nações para onde tinha ido.",np:1},
{v:22,t:"Por isso dize à casa de Israel: Assim diz o Senhor Deus: Não é por vossa causa que vou agir, casa de Israel, mas por causa do meu santo nome, que profanastes entre as nações para onde fostes.",np:1},
{v:23,t:"Santificarei o meu grande nome, profanado entre as nações, que vós profanastes no meio delas; e as nações saberão que eu sou o Senhor, oráculo do Senhor Deus, quando eu manifestar em vós a minha santidade diante dos seus olhos."},
{s:"Um coração novo e um espírito novo"},
{v:24,t:"Eu vos tirarei dentre as nações, vos reunirei de todos os países e vos levarei para a vossa terra."},
{v:25,t:"Derramarei sobre vós uma água pura, e ficareis purificados; eu vos purificarei de todas as vossas impurezas e de todos os vossos ídolos.",n:"A tradição cristã leu nestes versículos um anúncio do batismo e do dom do Espírito (compare João 3,5)."},
{v:26,t:"Eu vos darei um coração novo e porei dentro de vós um espírito novo; tirarei do vosso corpo o coração de pedra e vos darei um coração de carne."},
{v:27,t:"Porei dentro de vós o meu espírito e farei que andeis nos meus preceitos, guardeis os meus decretos e os pratiqueis."},
{v:28,t:"Habitareis na terra que dei aos vossos pais; sereis o meu povo, e eu serei o vosso Deus."},
{v:29,t:"Eu vos salvarei de todas as vossas impurezas; chamarei o trigo e o multiplicarei, e não mandarei mais a fome sobre vós."},
{v:30,t:"Multiplicarei o fruto das árvores e os produtos do campo, para que não sofrais mais entre as nações a vergonha da fome."},
{v:31,t:"Então vos lembrareis dos vossos maus caminhos e das vossas ações que não eram boas, e tereis nojo das vossas iniquidades e das vossas abominações."},
{v:32,t:"Não é por vossa causa que vou agir, oráculo do Senhor Deus; sabei-o bem. Envergonhai-vos e corai dos vossos caminhos, casa de Israel."},
{v:33,t:"Assim diz o Senhor Deus: No dia em que eu vos purificar de todas as vossas iniquidades, farei que as cidades sejam habitadas, e as ruínas, reconstruídas;",np:1},
{v:34,t:"a terra desolada será cultivada, ela que estava deserta aos olhos de todos os que passavam;"},
{v:35,t:"e dirão: Esta terra, que estava desolada, tornou-se como o jardim do Éden, e as cidades desertas, devastadas e destruídas, agora estão fortificadas e habitadas."},
{v:36,t:"E as nações que restarem ao vosso redor saberão que eu, o Senhor, reconstruí o que estava destruído e replantei o que estava devastado. Eu, o Senhor, falei e o farei."},
{v:37,t:"Assim diz o Senhor Deus: Ainda nisto me deixarei suplicar pela casa de Israel, para lhes fazer isto: eu os multiplicarei como um rebanho de homens,",np:1},
{v:38,t:"como o rebanho das ofertas sagradas, como o rebanho de Jerusalém nas suas festas; assim as cidades desertas ficarão cheias de rebanhos de homens, e saberão que eu sou o Senhor."}
];

window.TEXTOS_SEED["ezequiel"][37] = [
{s:"Os ossos secos"},
{v:1,t:"A mão do Senhor esteve sobre mim; ele me levou pelo espírito do Senhor e me pôs no meio de uma planície que estava cheia de ossos."},
{v:2,t:"Fez-me passar ao redor deles, por todos os lados: eram muitíssimos sobre a face da planície e estavam completamente secos."},
{v:3,t:"Ele me disse: Filho do homem, poderão reviver estes ossos? Eu respondi: Senhor Deus, tu o sabes."},
{v:4,t:"Ele me disse: Profetiza sobre estes ossos e dize-lhes: Ossos secos, ouvi a palavra do Senhor."},
{v:5,t:"Assim diz o Senhor Deus a estes ossos: Eis que farei entrar em vós o espírito, e vivereis;"},
{v:6,t:"porei sobre vós nervos, farei crescer sobre vós a carne, vos cobrirei de pele e vos darei o espírito, e vivereis; e sabereis que eu sou o Senhor.",n:"Em hebraico, a mesma palavra (ruah) significa espírito, sopro e vento; o capítulo joga com os três sentidos."},
{v:7,t:"Profetizei como me tinha sido ordenado. Enquanto eu profetizava, houve um ruído, e eis um tremor; e os ossos se aproximaram uns dos outros, cada osso ao seu osso."},
{v:8,t:"Olhei, e eis que sobre eles havia nervos, a carne tinha crescido, e a pele os cobria por cima; mas não havia espírito neles."},
{v:9,t:"Ele me disse: Profetiza ao espírito, profetiza, filho do homem, e dize ao espírito: Assim diz o Senhor Deus: Vem dos quatro ventos, espírito, e sopra sobre estes mortos, para que revivam."},
{v:10,t:"Profetizei como ele me tinha ordenado, e o espírito entrou neles; eles reviveram e se puseram de pé: era um exército imenso."},
{v:11,t:"Ele me disse: Filho do homem, estes ossos são toda a casa de Israel. Eis que eles dizem: Os nossos ossos secaram, a nossa esperança se acabou, estamos perdidos.",np:1},
{v:12,t:"Por isso profetiza e dize-lhes: Assim diz o Senhor Deus: Eis que vou abrir os vossos túmulos; eu vos farei sair dos vossos sepulcros, ó meu povo, e vos levarei à terra de Israel."},
{v:13,t:"E sabereis que eu sou o Senhor, quando eu abrir os vossos sepulcros e vos fizer sair dos vossos túmulos, ó meu povo."},
{v:14,t:"Porei em vós o meu espírito, e vivereis; eu vos estabelecerei na vossa terra, e sabereis que eu, o Senhor, falei e o farei, oráculo do Senhor Deus.",n:"A visão anuncia a restauração do povo exilado; a tradição cristã viu nela também uma imagem da ressurreição dos mortos."},
{s:"Um só reino, um só pastor"},
{v:15,t:"A palavra do Senhor me foi dirigida:"},
{v:16,t:"E tu, filho do homem, toma um pedaço de madeira e escreve nele: Judá e os filhos de Israel, seus companheiros. Toma depois outro pedaço de madeira e escreve nele: José, madeira de Efraim, e toda a casa de Israel, seus companheiros."},
{v:17,t:"Junta-os um ao outro, para formar um só pedaço de madeira, e eles serão um só na tua mão."},
{v:18,t:"E, quando os filhos do teu povo te pedirem que lhes expliques o que queres dizer com isso,"},
{v:19,t:"dize-lhes: Assim diz o Senhor Deus: Eis que vou tomar a madeira de José, que está na mão de Efraim, e as tribos de Israel que estão unidas a ele, e as juntarei à madeira de Judá, fazendo delas um só pedaço de madeira, e serão um só na minha mão."},
{v:20,t:"Os pedaços de madeira em que escreveres estarão na tua mão, à vista deles;"},
{v:21,t:"e dize-lhes: Assim diz o Senhor Deus: Eis que vou tomar os filhos de Israel do meio das nações para onde foram; vou reuni-los de todas as partes e levá-los para a sua terra;"},
{v:22,t:"farei deles uma só nação na terra, nos montes de Israel; um só rei reinará sobre todos eles; não serão mais duas nações, nem estarão mais divididos em dois reinos."},
{v:23,t:"Não se contaminarão mais com os seus ídolos, com as suas abominações e com todas as suas transgressões; eu os salvarei de todas as infidelidades com que pecaram e os purificarei; eles serão o meu povo, e eu serei o seu Deus."},
{v:24,t:"O meu servo Davi será rei sobre eles, e haverá um só pastor para todos eles; andarão nos meus decretos, guardarão os meus preceitos e os cumprirão.",n:"Compare 34,23–24; João 10,16."},
{v:25,t:"Habitarão na terra que dei ao meu servo Jacó, onde habitaram os vossos pais; eles, os seus filhos e os filhos dos seus filhos habitarão nela para sempre, e o meu servo Davi será o seu príncipe para sempre."},
{v:26,t:"Farei com eles uma aliança de paz, que será para eles uma aliança eterna; eu os estabelecerei e os multiplicarei e porei o meu santuário no meio deles para sempre."},
{v:27,t:"A minha morada estará junto deles; eu serei o seu Deus, e eles serão o meu povo.",n:"Compare Apocalipse 21,3."},
{v:28,t:"E as nações saberão que eu, o Senhor, santifico Israel, quando o meu santuário estiver no meio deles para sempre."}
];

window.TEXTOS_SEED["ezequiel"][38] = [
{s:"Gog, da terra de Magog"},
{v:1,t:"A palavra do Senhor me foi dirigida:"},
{v:2,t:"Filho do homem, volta o rosto contra Gog, da terra de Magog, príncipe supremo de Mosoc e de Tubal, e profetiza contra ele",n:"Gog e Magog: figura misteriosa do inimigo dos últimos tempos, vindo do extremo norte; compare Apocalipse 20,8. Príncipe supremo: o hebraico pode ser lido também: príncipe de Ros."},
{v:3,t:"e dize: Assim diz o Senhor Deus: Eis que estou contra ti, Gog, príncipe supremo de Mosoc e de Tubal;"},
{v:4,t:"eu te farei dar meia-volta, porei ganchos nas tuas mandíbulas e te farei sair com todo o teu exército, cavalos e cavaleiros, todos perfeitamente equipados, uma grande multidão com escudos e broquéis, todos empunhando a espada."},
{v:5,t:"Com eles estão os persas, os etíopes e os de Fut, todos com escudo e capacete;",np:1},
{v:6,t:"Gomer e todas as suas tropas, a casa de Togorma, do extremo norte, e todas as suas tropas: muitos povos estão contigo."},
{v:7,t:"Prepara-te e equipa-te, tu e toda a multidão reunida ao teu redor, e fica sob as minhas ordens."},
{v:8,t:"Depois de muitos dias serás convocado; no fim dos anos virás a uma terra que escapou da espada, cujos habitantes foram reunidos dentre muitos povos, nos montes de Israel, que por muito tempo ficaram desertos; ela foi tirada dentre os povos, e todos habitam nela em segurança."},
{v:9,t:"Subirás como uma tempestade, virás como uma nuvem para cobrir a terra, tu e todas as tuas tropas, e muitos povos contigo."},
{v:10,t:"Assim diz o Senhor Deus: Naquele dia te virão pensamentos ao coração, e conceberás um plano perverso",np:1},
{v:11,t:"e dirás: Subirei contra uma terra sem muralhas, irei contra gente tranquila, que vive em segurança; todos habitam sem muralhas e não têm trancas nem portas;"},
{v:12,t:"para saquear e pilhar, para estender a mão contra as ruínas novamente habitadas e contra um povo reunido dentre as nações, que adquiriu rebanhos e bens e habita no umbigo da terra.",n:"O umbigo da terra: Jerusalém, vista como o centro do mundo (compare 5,5)."},
{v:13,t:"Sabá, Dedan, os mercadores de Társis e todos os seus chefes te dirão: É para saquear que vens? É para pilhar que reuniste a tua multidão, para levar prata e ouro, para tomar rebanhos e bens e fazer um saque imenso?"},
{v:14,t:"Por isso profetiza, filho do homem, e dize a Gog: Assim diz o Senhor Deus: Não é verdade que naquele dia, quando o meu povo Israel habitar em segurança, tu te levantarás?",np:1},
{v:15,t:"Virás do teu lugar, do extremo norte, tu e muitos povos contigo, todos montados a cavalo, uma grande multidão e um exército poderoso."},
{v:16,t:"Subirás contra o meu povo Israel como uma nuvem para cobrir a terra. Isso acontecerá nos últimos dias: eu te trarei contra a minha terra, para que as nações me conheçam, quando eu manifestar em ti a minha santidade diante dos seus olhos, ó Gog."},
{s:"O julgamento de Gog"},
{v:17,t:"Assim diz o Senhor Deus: Tu és aquele de quem falei nos tempos antigos por meio dos meus servos, os profetas de Israel, que naqueles dias profetizaram durante anos que eu te traria contra eles."},
{v:18,t:"Naquele dia, no dia em que Gog vier contra a terra de Israel, oráculo do Senhor Deus, o meu furor subirá à minha ira."},
{v:19,t:"No meu ciúme, no fogo da minha ira, eu falei: Naquele dia haverá um grande terremoto na terra de Israel;"},
{v:20,t:"tremerão diante de mim os peixes do mar, as aves do céu, os animais do campo, todos os répteis que se arrastam sobre o solo e todos os homens que estão sobre a face da terra; os montes serão derrubados, os rochedos cairão, e todas as muralhas desabarão por terra."},
{v:21,t:"Chamarei contra ele a espada em todos os meus montes, oráculo do Senhor Deus; a espada de cada um se voltará contra o seu irmão."},
{v:22,t:"Eu o julgarei com a peste e com o sangue; farei cair uma chuva torrencial e pedras de granizo, fogo e enxofre sobre ele, sobre as suas tropas e sobre os muitos povos que estão com ele;"},
{v:23,t:"assim manifestarei a minha grandeza e a minha santidade e me darei a conhecer aos olhos de muitas nações; e saberão que eu sou o Senhor."}
];

window.TEXTOS_SEED["ezequiel"][39] = [
{s:"A derrota de Gog"},
{v:1,t:"Tu, pois, filho do homem, profetiza contra Gog e dize: Assim diz o Senhor Deus: Eis que estou contra ti, Gog, príncipe supremo de Mosoc e de Tubal;"},
{v:2,t:"eu te farei dar meia-volta, te conduzirei, te farei subir do extremo norte e te levarei aos montes de Israel."},
{v:3,t:"Quebrarei o arco na tua mão esquerda e farei cair as flechas da tua mão direita."},
{v:4,t:"Cairás sobre os montes de Israel, tu, todas as tuas tropas e os povos que estão contigo; eu te entreguei como alimento às aves de rapina, a toda espécie de pássaros e aos animais do campo:"},
{v:5,t:"cairás em campo aberto, pois eu falei, oráculo do Senhor Deus."},
{v:6,t:"Mandarei fogo sobre Magog e sobre os que habitam em segurança nas ilhas, e saberão que eu sou o Senhor."},
{v:7,t:"Farei conhecer o meu santo nome no meio do meu povo Israel e não deixarei mais profanar o meu santo nome; e as nações saberão que eu sou o Senhor, o Santo em Israel."},
{v:8,t:"Eis que vem e se cumpre, oráculo do Senhor Deus: este é o dia de que falei.",np:1},
{v:9,t:"Os habitantes das cidades de Israel sairão e queimarão as armas, os escudos e os broquéis, os arcos e as flechas, os bastões e as lanças; farão fogo com elas durante sete anos.",np:1},
{v:10,t:"Não precisarão trazer lenha do campo nem cortá-la nas florestas, pois farão fogo com as armas; saquearão os que os tinham saqueado e despojarão os que os tinham despojado, oráculo do Senhor Deus."},
{s:"O sepultamento de Gog"},
{v:11,t:"Naquele dia darei a Gog um lugar famoso para sepultura em Israel: o vale dos Viajantes, a oriente do mar, que fecha o caminho aos que passam; ali sepultarão Gog e toda a sua multidão, e ele se chamará vale da Multidão de Gog.",n:"Em hebraico, Hamon-Gog; jogo de palavras com o nome da cidade de Hamona (v. 16)."},
{v:12,t:"A casa de Israel os sepultará durante sete meses, para purificar a terra;"},
{v:13,t:"todo o povo da terra os sepultará, e será para eles um dia memorável aquele em que eu manifestar a minha glória, oráculo do Senhor Deus."},
{v:14,t:"Designarão homens encarregados de percorrer continuamente a terra, para sepultar os que tiverem ficado sobre a face da terra, a fim de purificá-la; depois de sete meses começarão a busca"},
{v:15,t:"e percorrerão a terra; quando virem um osso humano, colocarão ao lado dele um sinal, até que os coveiros o sepultem no vale da Multidão de Gog."},
{v:16,t:"Também haverá uma cidade chamada Hamona. Assim purificarão a terra."},
{s:"O banquete das aves"},
{v:17,t:"Tu, pois, filho do homem, assim diz o Senhor Deus, dize às aves de toda espécie e a todos os animais do campo: Reuni-vos, apressai-vos, vinde de todos os lados para o sacrifício que vou imolar para vós, um grande sacrifício sobre os montes de Israel, para comerdes carne e beberdes sangue.",n:"Nota do tradutor: imagem apocalíptica, retomada em Apocalipse 19,17–18; o texto não foi suavizado."},
{v:18,t:"Comereis a carne dos valentes e bebereis o sangue dos príncipes da terra: carneiros, cordeiros, bodes e touros, todos cevados em Basã;"},
{v:19,t:"comereis gordura até vos fartardes e bebereis sangue até vos embriagardes, do sacrifício que vou imolar para vós."},
{v:20,t:"Na minha mesa vos fartareis de cavalos e de animais de tiro, de valentes e de toda espécie de guerreiros, oráculo do Senhor Deus."},
{v:21,t:"Manifestarei a minha glória entre as nações, e todas as nações verão o julgamento que executei e a mão que pus sobre eles;",np:1},
{v:22,t:"e a casa de Israel saberá que eu sou o Senhor, seu Deus, daquele dia em diante;"},
{v:23,t:"e as nações saberão que a casa de Israel foi para o exílio por causa da sua iniquidade, porque me abandonaram; por isso escondi deles o meu rosto e os entreguei nas mãos dos seus inimigos, e todos caíram pela espada."},
{v:24,t:"Tratei-os segundo a sua impureza e as suas transgressões, e escondi deles o meu rosto."},
{s:"A restauração de Israel"},
{v:25,t:"Por isso assim diz o Senhor Deus: Agora mudarei a sorte de Jacó, terei compaixão de toda a casa de Israel e serei zeloso do meu santo nome."},
{v:26,t:"Eles carregarão a sua vergonha e todas as infidelidades que cometeram contra mim, quando habitarem em segurança na sua terra, sem que ninguém os amedronte,"},
{v:27,t:"quando eu os fizer voltar dentre os povos, os reunir dos países dos seus inimigos e manifestar neles a minha santidade aos olhos de muitas nações."},
{v:28,t:"E saberão que eu sou o Senhor, seu Deus, porque os levei para o exílio entre as nações e os reuni na sua terra, sem deixar nenhum deles lá."},
{v:29,t:"Não esconderei mais deles o meu rosto, pois derramei o meu espírito sobre a casa de Israel, oráculo do Senhor Deus."}
];

window.TEXTOS_SEED["ezequiel"][40] = [
{s:"A visão do novo templo"},
{v:1,t:"No vigésimo quinto ano da nossa deportação, no começo do ano, no dia dez do mês, catorze anos depois da queda da cidade, naquele mesmo dia a mão do Senhor esteve sobre mim e me levou para lá.",n:"Em abril de 573 antes de Cristo. Os capítulos 40–48 descrevem, em visão, o templo, o culto e a terra de Israel restaurados. O texto hebraico destes capítulos, muito técnico, é muitas vezes incerto; segue-se a Nova Vulgata, que com frequência adota as leituras da tradução grega."},
{v:2,t:"Em visões de Deus, ele me levou à terra de Israel e me pôs sobre um monte muito alto, sobre o qual havia, ao sul, algo como a construção de uma cidade."},
{v:3,t:"Levou-me para lá, e eis um homem cujo aspecto era como o aspecto do bronze; tinha na mão um cordel de linho e uma cana de medir, e estava de pé junto à porta."},
{v:4,t:"Esse homem me disse: Filho do homem, olha com os teus olhos, ouve com os teus ouvidos e presta atenção a tudo o que vou mostrar-te, pois foste trazido aqui para que eu te mostrasse; anuncia à casa de Israel tudo o que vires."},
{s:"O muro e a porta oriental"},
{v:5,t:"E eis que havia um muro por fora, ao redor do templo, por todos os lados. Na mão do homem estava a cana de medir, de seis côvados, cada côvado de um côvado e um palmo; ele mediu a largura da construção: uma cana; e a altura: uma cana.",n:"O côvado longo tinha cerca de cinquenta e dois centímetros; a cana media pouco mais de três metros."},
{v:6,t:"Depois foi à porta que dava para o oriente, subiu os seus degraus e mediu o limiar da porta: uma cana de largura;",np:1},
{v:7,t:"cada câmara: uma cana de comprimento e uma cana de largura; entre as câmaras, cinco côvados; e o limiar da porta, junto ao vestíbulo da porta, do lado de dentro: uma cana."},
{v:8,t:"Mediu o vestíbulo da porta:"},
{v:9,t:"oito côvados; e os seus pilares, dois côvados; o vestíbulo da porta ficava do lado de dentro."},
{v:10,t:"As câmaras da porta oriental eram três de um lado e três do outro; as três tinham a mesma medida, e também os pilares de um lado e do outro tinham a mesma medida."},
{v:11,t:"Mediu a largura da entrada da porta: dez côvados; e o comprimento da porta: treze côvados;"},
{v:12,t:"diante das câmaras havia um parapeito de um côvado, de um lado e do outro; e as câmaras tinham seis côvados de um lado e do outro."},
{v:13,t:"Mediu a porta, do teto de uma câmara ao teto da câmara oposta: vinte e cinco côvados de largura, de uma entrada à outra;",n:"A Nova Vulgata omite o v. 14, de texto hebraico muito incerto."},
{v:15,t:"e da frente da entrada da porta até a frente do vestíbulo interior da porta: cinquenta côvados."},
{v:16,t:"As câmaras e os seus pilares, do lado de dentro da porta, tinham janelas com molduras, ao redor, por todos os lados; também o vestíbulo tinha janelas ao redor, do lado de dentro, e sobre os pilares havia palmeiras desenhadas."},
{s:"O átrio exterior"},
{v:17,t:"Depois me levou ao átrio exterior, e eis que havia salas e um pavimento de pedra ao redor do átrio; trinta salas davam para o pavimento."},
{v:18,t:"O pavimento ficava ao lado das portas, correspondendo ao comprimento das portas; era o pavimento inferior."},
{v:19,t:"Mediu a largura, desde a frente da porta inferior até a frente do átrio interior, por fora: cem côvados. Assim era no oriente, e assim no norte."},
{v:20,t:"Mediu também o comprimento e a largura da porta do átrio exterior que dava para o norte;",np:1},
{v:21,t:"as suas câmaras, três de um lado e três do outro, os seus pilares e o seu vestíbulo tinham as mesmas medidas da primeira porta: cinquenta côvados de comprimento e vinte e cinco côvados de largura."},
{v:22,t:"As janelas do seu vestíbulo e as palmeiras esculpidas tinham as mesmas medidas da porta que dava para o oriente; subia-se a ela por sete degraus, e o seu vestíbulo ficava do lado de dentro.",np:1},
{v:23,t:"Havia uma porta do átrio interior diante da porta do norte, como na porta oriental; e ele mediu de porta a porta: cem côvados."},
{v:24,t:"Depois me levou para o lado sul, e eis uma porta que dava para o sul; mediu os seus pilares e o seu vestíbulo: tinham as mesmas medidas das anteriores."},
{v:25,t:"Ela e o seu vestíbulo tinham janelas ao redor, como as outras janelas; o comprimento era de cinquenta côvados, e a largura, de vinte e cinco côvados.",np:1},
{v:26,t:"Subia-se a ela por sete degraus, e o seu vestíbulo ficava do lado de dentro; nos seus pilares havia palmeiras esculpidas, uma de um lado e outra do outro.",np:1},
{v:27,t:"O átrio interior tinha uma porta do lado sul; e ele mediu de porta a porta, do lado sul: cem côvados."},
{s:"As portas do átrio interior"},
{v:28,t:"Depois me levou ao átrio interior pela porta sul e mediu a porta sul: tinha as mesmas medidas das anteriores;"},
{v:29,t:"as suas câmaras, os seus pilares e o seu vestíbulo tinham as mesmas medidas; ela e o seu vestíbulo tinham janelas ao redor. O comprimento era de cinquenta côvados, e a largura, de vinte e cinco côvados.",n:"A Nova Vulgata omite o v. 30, que falta na tradução grega e repete dados anteriores."},
{v:31,t:"O seu vestíbulo dava para o átrio exterior; nos seus pilares havia palmeiras, e subia-se a ela por oito degraus."},
{v:32,t:"Depois me levou ao átrio interior, pelo lado oriental, e mediu a porta: tinha as mesmas medidas das anteriores;",np:1},
{v:33,t:"as suas câmaras, os seus pilares e o seu vestíbulo eram como os anteriores; ela e o seu vestíbulo tinham janelas ao redor. O comprimento era de cinquenta côvados, e a largura, de vinte e cinco côvados."},
{v:34,t:"O seu vestíbulo dava para o átrio exterior; nos seus pilares havia palmeiras esculpidas, de um lado e do outro, e subia-se a ela por oito degraus."},
{v:35,t:"Depois me levou à porta que dava para o norte e a mediu: tinha as mesmas medidas das anteriores,"},
{v:36,t:"as suas câmaras, os seus pilares e o seu vestíbulo; e tinha janelas ao redor. O comprimento era de cinquenta côvados, e a largura, de vinte e cinco côvados."},
{v:37,t:"O seu vestíbulo dava para o átrio exterior; nos seus pilares havia palmeiras esculpidas, de um lado e do outro, e subia-se a ela por oito degraus."},
{s:"As salas e as mesas para os sacrifícios"},
{v:38,t:"Havia uma sala cuja porta dava para o vestíbulo da porta; ali se lavava o holocausto."},
{v:39,t:"No vestíbulo da porta havia duas mesas de um lado e duas mesas do outro, para imolar sobre elas o holocausto e os sacrifícios pelo pecado e pela culpa."},
{v:40,t:"Do lado de fora do vestíbulo, junto à entrada da porta que dava para o norte, havia duas mesas; e do outro lado do vestíbulo da porta, duas mesas."},
{v:41,t:"Havia quatro mesas de um lado e quatro mesas do outro, ao lado da porta: eram oito mesas, sobre as quais se imolavam as vítimas."},
{v:"42a",t:"Havia ainda quatro mesas para o holocausto, feitas de pedras lavradas, de um côvado e meio de comprimento, um côvado e meio de largura e um côvado de altura,",np:1,n:"A Nova Vulgata reordena aqui as partes dos vv. 42–43, para dar sentido ao texto."},
{v:"43a",t:"com uma borda de um palmo, voltada para dentro, ao redor;"},
{v:"42b",t:"sobre elas se punham os utensílios com que se imolavam o holocausto e as vítimas;"},
{v:"43b",t:"e sobre as mesas, a carne das ofertas."},
{v:44,t:"Do lado de fora da porta interior havia duas salas no átrio interior: uma ao lado da porta que dava para o norte, com a frente voltada para o sul, e outra ao lado da porta sul, com a frente voltada para o norte."},
{v:45,t:"Ele me disse: Esta sala, que dá para o sul, é para os sacerdotes que cuidam do serviço do templo;"},
{v:46,t:"e a sala que dá para o norte é para os sacerdotes que cuidam do serviço do altar: são os filhos de Sadoc, que, dentre os filhos de Levi, se aproximam do Senhor para servi-lo.",n:"Sadoc: sacerdote do tempo de Davi e de Salomão (1 Reis 2,35); Ezequiel reserva aos seus descendentes o serviço do altar (44,15)."},
{s:"O vestíbulo do templo"},
{v:47,t:"Mediu o átrio: cem côvados de comprimento e cem côvados de largura, em quadrado. O altar estava diante do templo."},
{v:48,t:"Levou-me ao vestíbulo do templo e mediu os pilares do vestíbulo: cinco côvados de um lado e cinco do outro; a largura da porta: catorze côvados; e as paredes laterais da porta: três côvados de um lado e três do outro;"},
{v:49,t:"o comprimento do vestíbulo era de vinte côvados, e a largura, de doze côvados; subia-se a ele por dez degraus, e havia colunas junto aos pilares, uma de um lado e outra do outro."}
];
